(function(A){Object.assign(A.D,{"G1679":{"l":"ἐλπίζω","o":31,"ar":"<f><o>ἐλπίζω </o></f> <s><b>يترقّب، ينتظر، يرجو</b>: مع منصوب الشيء، <r v=\"Rom.8.24\"></r>، <r v=\"Rom.8.25\"></r>، <r v=\"1Cor.13.7\"></r>، <r v=\"Heb.11.1\"></r>؛ مع قابل الشيء، <r v=\"Matt.12.21\"></r>؛ يليه <g>καθώς</g>، <r v=\"2Cor.8.5\"></r>؛ مع المصدر، <r v=\"Luke.6.34\"></r> <r v=\"Luke.23.8\"></r>، <r v=\"Acts.26.7\"></r>، <r v=\"Rom.15.24\"></r>، <r v=\"1Cor.16.7\"></r>، <r v=\"2Cor.5.11\"></r>، <r v=\"Phil.2.19\"></r>، <r v=\"Phil.2.23\"></r>، <r v=\"1Tim.3.14\"></r>، <r v=\"2John.1.12\"></r>، <r v=\"3John.1.14\"></r>؛ يليه <g>ὅτι</g>، مع المضارع، <r v=\"Luke.24.21\"></r>؛ مع المستقبل، <r v=\"Acts.24.26\"></r>، <r v=\"2Cor.1.13\"></r> <r v=\"2Cor.13.6\"></r>، <r v=\"Phlm.1.22\"></r>. وكما في السبعينية (وخاصةً في التام، قارن <r v=\"1Tim.4.10\"></r>)، مع حرف جر؛ <g>εἰς</g>، <r v=\"John.5.45\"></r>، <r v=\"1Pet.3.5\"></r>؛ يليه <g>ὅτι</g>، <r v=\"2Cor.1.10\"></r>؛ <g>ἐπί</g>، مع القابل، <r v=\"Rom.15.12\"></r> <i>(السبعينية)</i>، <r v=\"1Tim.4.10\"></r> <r v=\"1Tim.6.17\"></r>؛ <g>ἐν</g>، <r v=\"1Cor.15.19\"></r>؛ مع المنصوب، <r v=\"1Pet.1.13\"></r> (الأمر الماضي البسيط)؛ <g>τ. θεόν</g>، <r v=\"1Tim.5.5\"></r> (قارن <g>ἀπ-, προ-ελπίζω</g>).†</s>","en":"<f><o>ἐλπίζω </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H982\">בָּטַח</h>, also for <h n=\"H2620\">חָסָה</h>, <h n=\"H3176\">יָחַל</h> pi., hi., etc. ;] </e> </et> <s><b>to look for, expect, hope</b> (<b>for</b>): c. acc rei, <r v=\"Rom.8.24\"></r>, <r v=\"Rom.8.25\"></r>, <r v=\"1Cor.13.7\"></r>, <r v=\"Heb.11.1\"></r>; c. dat. rei (<g>τ. τύχῃ</g>, Thuc., iii, 97, 2), <r v=\"Matt.12.21\"></r>; seq. <g>καθώς</g>, <r v=\"2Cor.8.5\"></r>; c. inf., <r v=\"Luke.6.34\"></r> <r v=\"Luke.23.8\"></r>, <r v=\"Acts.26.7\"></r>, <r v=\"Rom.15.24\"></r>, <r v=\"1Cor.16.7\"></r>, <r v=\"2Cor.5.11\"></r>, <r v=\"Phil.2.19\"></r>, <r v=\"Phil.2.23\"></r>, <r v=\"1Tim.3.14\"></r>, <r v=\"2John.1.12\"></r>, <r v=\"3John.1.14\"></r>; seq. <g>ὅτι</g>, c. pres., <r v=\"Luke.24.21\"></r>; c. fut., <r v=\"Acts.24.26\"></r>, <r v=\"2Cor.1.13\"></r> <r v=\"2Cor.13.6\"></r>, <r v=\"Phlm.1.22\"></r>. As in LXX (WM, § xxxiii, d; and esp. in the pf., Ellic. on <r v=\"1Tim.4.10\"></r>; Bl., § 59, 2), c. prep.; <g>εἰς</g>, <r v=\"John.5.45\"></r> (v. Ellis., l.c.), <r v=\"1Pet.3.5\"></r>; seq. <g>ὅτι</g>, <r v=\"2Cor.1.10\"></r>; <g>ἐπί</g>, c. dat., <r v=\"Rom.15.12\"></r> <i>(LXX)</i>, <r v=\"1Tim.4.10\"></r> <r v=\"1Tim.6.17\"></r>; <g>ἐν</g>, <r v=\"1Cor.15.19\"></r>; c. acc, <r v=\"1Pet.1.13\"></r> (aor. imper. v. Bl., § 58, 2); <g>τ. θεόν</g>, <r v=\"1Tim.5.5\"></r> (of. <g>ἀπ-, προ-ελπίζω</g>, v. Cremer, 255).†</s>"},"G1699":{"l":"ἐμός","o":63,"ar":"<f><o>ἐμός</o>، <g>-ή, -όν </g></f> <s>ضمير ملكية للمتكلم، يقوم مقام المضاف إليه المؤكَّد <g>ἐμοῦ</g>، </s> <s><b>لي</b>، <b>خاصتي</b>، بالمعنيين الفاعلي والمفعولي، أي ما يخصني أو يصدر عني أو يتعلق بي: <r v=\"Matt.18.20\"></r>، <r v=\"Mark.8.38\"></r>، <r v=\"John.3.29\"></r> (وهي أكثر ورودًا في هذا الإنجيل)، وفي مواضع أخرى؛ مطلقًا، <g>τὸ ἐμόν, τὰ ἐμά</g>، <r v=\"Matt.20.15\"></r> <r v=\"Matt.25.27\"></r>، <r v=\"Luke.15.31\"></r>، <r v=\"John.10.14\"></r> <r v=\"John.16.14\"></r>، <r v=\"John.16.15\"></r> <r v=\"John.17.10\"></r>؛ = المضاف إليه المفعولي، <g>εἰς τ. ἐμὴν ἀνάμνησιν</g>، <r v=\"Luke.22.19\"></r>، <r v=\"1Cor.11.24\"></r>، <r v=\"1Cor.11.25\"></r>؛ مع مضاف إليه تفسيري، <g>τ. ἐμῇ χειρὶ Παύλου</g>، <r v=\"1Cor.16.21\"></r>، <r v=\"Col.4.18\"></r>، <r v=\"2Thess.3.17\"></r> </s>","en":"<f><o>ἐμός</o>, <g>-ή, -όν </g></f> <s>poss. prop. of first pers., representing the em­phasized gen. <g>ἐμοῦ</g>, </s> <s><b>mine</b>, subjectively and objectively, i.e. belonging to, proceeding from or related to me: <r v=\"Matt.18.20\"></r>, <r v=\"Mark.8.38\"></r>, <r v=\"John.3.29\"></r> (most freq. in this gospel), al.; absol., <g>τὸ ἐμόν, τὰ ἐμά</g>, <r v=\"Matt.20.15\"></r> <r v=\"Matt.25.27\"></r>, <r v=\"Luke.15.31\"></r>, <r v=\"John.10.14\"></r> <r v=\"John.16.14\"></r>, <r v=\"John.16.15\"></r> <r v=\"John.17.10\"></r>; = gen. obj. (cl.), <g>εἰς τ. ἐμὴν ἀνάμνησιν</g>, <r v=\"Luke.22.19\"></r>, <r v=\"1Cor.11.24\"></r>, <r v=\"1Cor.11.25\"></r>; c. gen. expl., <g>τ. ἐμῇ χειρὶ Παύλου</g>, <r v=\"1Cor.16.21\"></r>, <r v=\"Col.4.18\"></r>, <r v=\"2Thess.3.17\"></r> </s>"},"G1683":{"l":"ἐμαυτοῦ","o":37,"ar":"<f><o>ἐμαυτοῦ</o>، <g>-ῆς, -οῦ</g>، </f> <s>ضمير انعكاسي للمتكلم، لا يُستعمل إلا في المضاف إليه والقابل والمنصوب المفرد، </s> <s><b>نفسي</b>، <b>ذاتي</b>: <r v=\"Luke.7.7\"></r>، وفي مواضع أخرى؛ <g>ἀπ’ ἐ.</g>، <r v=\"John.5.30\"></r> <r v=\"John.7.17\"></r>، <r v=\"John.7.28\"></r> <r v=\"John.8.28\"></r>، <r v=\"John.8.42\"></r> <r v=\"John.10.18\"></r> <r v=\"John.14.10\"></r>؛ <g>ὑπ’ ἐμαυτόν</g>، <r v=\"Matt.8.9\"></r>، <r v=\"Luke.7.8\"></r> </s>","en":"<f><o>ἐμαυτοῦ</o>, <g>-ῆς, -οῦ</g>, </f> <s>reflex pron. of first pers., used only in gen., dat. and acc sing., </s> <s><b>of myself</b>: <r v=\"Luke.7.7\"></r>, al.; <g>ἀπ’ ἐ.</g>, <r v=\"John.5.30\"></r> <r v=\"John.7.17\"></r>, <r v=\"John.7.28\"></r> <r v=\"John.8.28\"></r>, <r v=\"John.8.42\"></r> <r v=\"John.10.18\"></r> <r v=\"John.14.10\"></r>; <g>ὑπ’ ἐμαυτόν</g>, <r v=\"Matt.8.9\"></r>, <r v=\"Luke.7.8\"></r> </s>"},"G1677":{"l":"ἐλλογάω","o":2,"ar":"<f>*† <o>ἐλλογάω</o>، <g>-ῶ</g></f> <s><b>حسب على حساب أحد، نسب إليه</b>: <r v=\"Phlm.1.18\"></r>؛ عن الخطية: <r v=\"Rom.5.13\"></r>.†</s>","en":"<f>*† <o>ἐλλογάω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(a <g>κοινή</g> word, elsewhere usually <g>-έω</g>; cf. Bl., § 22, 2), </e> </et> <s><b>to charge to one's account, impute</b>: <r v=\"Phlm.1.18\"></r> (on parallels, cf. Deiss., <i>LAE</i>, 79 f., 335 f.; Milligan, <i>NTD</i>, 73; MM, <i>Exp.</i>, xii); of sin, <r v=\"Rom.5.13\"></r> (Cremer, 400).†</s>"},"G1656":{"l":"ἔλεος","o":27,"ar":"<f><o>ἔλεος</o>، <g>-ους, τό</g></f> <s><b>رحمة، شفقة، رأفة</b>؛ </s> <s n=\"1.\">عن البشر: <r v=\"Matt.9.13\"></r> <i>(السبعينية)</i> <r v=\"Matt.12.7\"></r> <r v=\"Matt.23.23\"></r>؛ <g>ποιεῖν ἔ.</g> (وكذلك يليه <g>μετά</g> مع المضاف إليه؛ قارن <i>العبرية</i> <h n=\"H5973\">עִם</h> <h n=\"H2617\">חֶסֶד</h> <h n=\"H6213\">עָשָׂה</h>، <r v=\"Gen.21.23\"></r>، وفي مواضع أخرى)، <r v=\"Luke.10.37\"></r>، <r v=\"Jas.2.13\"></r> <r v=\"Jas.3.17\"></r>. </s> <s n=\"2.\">عن الله: <r v=\"Luke.1.50\"></r>، <r v=\"Luke.1.54\"></r> <r v=\"Luke.1.58\"></r>، <r v=\"Rom.15.9\"></r>، <r v=\"Eph.2.4\"></r>، <r v=\"2Tim.1.16\"></r> <r v=\"2Tim.1.18\"></r>، <r v=\"Titus.3.5\"></r>، <r v=\"Heb.4.16\"></r>، <r v=\"1Pet.1.3\"></r>؛ خاصةً في البركات الرسولية، <r v=\"Gal.6.16\"></r>، <r v=\"1Tim.1.2\"></r>، <r v=\"2Tim.1.2\"></r>، <r v=\"2John.1.3\"></r>، <r v=\"Jude.1.2\"></r>؛ <g>σκευὴ ἐλέους</g>، <r v=\"Rom.9.23\"></r>؛ <g>σπλάγχνα ἐλέους</g>، <r v=\"Luke.1.78\"></r>؛ <g>ποιεῖν ἔ.</g> (انظر أعلاه)، <r v=\"Luke.1.72\"></r>؛ <g>τ. ὑμετέρῳ ἐλέει</g>، <r v=\"Rom.11.31\"></r>. </s> <s n=\"3.\">عن المسيح: <r v=\"Jude.1.21\"></r>.†</s>","en":"<f><o>ἔλεος</o>, <g>-ους, τό</g></f> <et> <e t=\"derivation\">(cl. <g>-ου, ὁ</g>, and so Rec., <r v=\"Matt.9.13\"></r> <r v=\"Matt.12.7\"></r> <r v=\"Matt.23.23\"></r>, <r v=\"Titus.3.5\"></r>, <r v=\"Heb.4.16\"></r>; on the Hellenistic form <g>τό ἔ.</g>, v. WH, <i>App.</i>, 158; M, <i>Pr.</i>, 60; Mayser, 277; Kühner, i, 515), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2617\">חֶסֶד</h> ;] </e> </et> <s><b>mercy, pity, compassion</b>; </s> <s n=\"1.\">of men: <r v=\"Matt.9.13\"></r> <i>(LXX)</i> <r v=\"Matt.12.7\"></r> <r v=\"Matt.23.23\"></r>; <g>ποιεῖν ἔ.</g> (and id. seq. <g>μετά</g>, c. gen.; cf. <i>Heb.</i> <h n=\"H5973\">עִם</h> <h n=\"H2617\">חֶסֶד</h> <h n=\"H6213\">עָשָׂה</h>, <r v=\"Gen.21.23\"></r>, al.), <r v=\"Luke.10.37\"></r>, <r v=\"Jas.2.13\"></r> <r v=\"Jas.3.17\"></r>. </s> <s n=\"2.\">Of God: <r v=\"Luke.1.50\"></r>, <r v=\"Luke.1.54\"></r> <r v=\"Luke.1.58\"></r>, <r v=\"Rom.15.9\"></r>, <r v=\"Eph.2.4\"></r>, <r v=\"2Tim.1.16\"></r> <r v=\"2Tim.1.18\"></r>, <r v=\"Titus.3.5\"></r>, <r v=\"Heb.4.16\"></r>, <r v=\"1Pet.1.3\"></r>; esp. in benedictions, <r v=\"Gal.6.16\"></r>, <r v=\"1Tim.1.2\"></r>, <r v=\"2Tim.1.2\"></r>, <r v=\"2John.1.3\"></r>, <r v=\"Jude.1.2\"></r>; <g>σκευὴ ἐλέους</g>, <r v=\"Rom.9.23\"></r>; <g>σπλάγχνα ἐλέους</g>, <r v=\"Luke.1.78\"></r>; <g>ποιεῖν ἔ.</g> (v. supr.), <r v=\"Luke.1.72\"></r>; <g>τ. ὑμετέρῳ ἐλέει</g>, <r v=\"Rom.11.31\"></r>. </s> <s n=\"3.\">Of Christ: <r v=\"Jude.1.21\"></r>.†</s> <sy><i>SYN.</i>: <g>οἰκτιρμός</g> (v.s. <x><g>ἐλεέω</g></x>) </sy>"},"G1658":{"l":"ἐλεύθερος","o":23,"ar":"<f><o>ἐλεύθερος</o>، <g>-α, -ον </g></f> <s><b>حُرّ</b>؛ </s> <s n=\"(a)\">بالمعنى المدني، أي ليس عبدًا: <r v=\"John.8.33\"></r>، <r v=\"1Cor.7.21\"></r>، <r v=\"1Cor.7.22\"></r> <r v=\"1Cor.12.13\"></r>، <r v=\"Gal.3.28\"></r>، <r v=\"Eph.6.8\"></r>، <r v=\"Col.3.11\"></r>، <r v=\"Rev.6.15\"></r> <r v=\"Rev.13.16\"></r> <r v=\"Rev.19.18\"></r>؛ في المؤنث، <r v=\"Gal.4.22\"></r>، <r v=\"Gal.4.23\"></r>، <r v=\"Gal.4.30\"></r>؛ </s> <s n=\"(b)\">من جهة القيد والالتزام عمومًا: <r v=\"Matt.17.26\"></r>، <r v=\"1Cor.9.1\"></r>؛ يليه <g>ἐκ</g>، <r v=\"1Cor.9.19\"></r>؛ <g>ἀπό</g>، <r v=\"Rom.7.3\"></r>؛ مع المصدر، <r v=\"1Cor.7.39\"></r>؛ من الناموس، <r v=\"Gal.4.26\"></r>، <r v=\"1Pet.2.16\"></r>؛ من الخطية، <r v=\"John.8.36\"></r>؛ <g>τῇ δικαιοσύνῃ</g>، <b>من جهة البر</b>، <r v=\"Rom.6.20\"></r>.†</s>","en":"<f><o>ἐλεύθερος</o>, <g>-α, -ον </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2670\">חׇפְשִׁי</h> ;] </e> </et> <s><b>free</b>; </s> <s n=\"(a)\">in civil sense, not a slave: <r v=\"John.8.33\"></r>, <r v=\"1Cor.7.21\"></r>, <r v=\"1Cor.7.22\"></r> <r v=\"1Cor.12.13\"></r>, <r v=\"Gal.3.28\"></r>, <r v=\"Eph.6.8\"></r>, <r v=\"Col.3.11\"></r>, <r v=\"Rev.6.15\"></r> <r v=\"Rev.13.16\"></r> <r v=\"Rev.19.18\"></r>; fem., <r v=\"Gal.4.22\"></r>, <r v=\"Gal.4.23\"></r>, <r v=\"Gal.4.30\"></r>; </s> <s n=\"(b)\">as regards restraint and obligation in general: <r v=\"Matt.17.26\"></r>, <r v=\"1Cor.9.1\"></r>; seq. <g>ἐκ</g>, <r v=\"1Cor.9.19\"></r>; <g>ἀπό</g>, <r v=\"Rom.7.3\"></r>; c. inf., <r v=\"1Cor.7.39\"></r>; from the law, <r v=\"Gal.4.26\"></r>, <r v=\"1Pet.2.16\"></r>; from sin, <r v=\"John.8.36\"></r>; <g>τῇ δικαιοσύνῃ</g>, <b>as regards righteousness</b>, <r v=\"Rom.6.20\"></r> (Cremer, 249).†</s>"},"G1647":{"l":"ἐλάχιστος","o":14,"ar":"<f><o>ἐλάχιστος</o>، <g>-η, -ον</g></f> <s><b>الأصغر، الأقل</b>: بمعنى صيغة التفضيل العليا الحقيقي، <r v=\"1Cor.15.9\"></r>؛ وفي غير ذلك، كما هو المعتاد في اليونانية المتأخرة، للتوكيد والمبالغة؛ <r v=\"Matt.2.6\"></r> <i>(السبعينية)</i> <r v=\"Matt.25.40\"></r>، <r v=\"Matt.25.45\"></r>، <r v=\"Luke.12.26\"></r> <r v=\"Luke.16.10\"></r> <r v=\"Luke.19.17\"></r>، <r v=\"1Cor.4.3\"></r> <r v=\"1Cor.6.2\"></r>، <r v=\"Jas.3.4\"></r>؛ <g>ἐ. ἐν τ. βασιλείᾳ τ. οὐρανῶν</g>، <r v=\"Matt.5.19\"></r>. صيغة التفضيل: <g>ἐλαχιστότερος</g>؛ <b>أصغر من أصغر الجميع</b>: <r v=\"Eph.3.8\"></r>.†</s>","en":"<f><o>ἐλάχιστος</o>, <g>-η, -ον</g></f> <et> <e t=\"derivation\">(v.s. <g>ἐλάσσων</g>), </e> </et> <s><b>smallest, least</b>: as proper superlat., <r v=\"1Cor.15.9\"></r>; elsewhere, as usually in late Gk., intensive (B1., § 11, 3); <r v=\"Matt.2.6\"></r> <i>(LXX)</i> <r v=\"Matt.25.40\"></r>, <r v=\"Matt.25.45\"></r>, <r v=\"Luke.12.26\"></r> <r v=\"Luke.16.10\"></r> <r v=\"Luke.19.17\"></r>, <r v=\"1Cor.4.3\"></r> <r v=\"1Cor.6.2\"></r>, <r v=\"Jas.3.4\"></r>; <g>ἐ. ἐν τ. βασιλείᾳ τ. οὐρανῶν</g>, <r v=\"Matt.5.19\"></r> (v. Dalman, <i>Words</i>, 113). Compar., <g>ἐλαχιστότερος</g> (for corresp. superl., v. LS; v. also Bl., § 44, 3); <b>less than the least</b>: <r v=\"Eph.3.8\"></r>.†</s>"},"G1625":{"l":"ἐκτρέφω","o":2,"ar":"<f><o>ἐκ-τρέφω </o></f> <s n=\"1.\">أصلاً، عن الأولاد، <b>يُنشئ، يربّي</b>: <r v=\"Eph.6.4\"></r>. </s> <s n=\"2.\"><b>يقوت، يغذّي</b>: <r v=\"Eph.5.29\"></r>.†</s>","en":"<f><o>ἐκ-τρέφω </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H1431\">גָּדַל</h>, etc. ;] </e> </et> <s n=\"1.\">prop., of children, <b>to nurture, bring up</b>: <r v=\"Eph.6.4\"></r>. </s> <s n=\"2.\"><b>to nourish</b>: <r v=\"Eph.5.29\"></r>.†</s>"},"G1691":{"l":"ἐγώ","o":2572,"ar":"<f><o>ἐγώ</o>، المضاف إليه إلخ: <g>ἐμοῦ, ἐμοί, ἐμέ</g> (الصيغ الملحقة <g>μου, μοι, με</g>)، الجمع <g>ἡμεῖς, -ῶν, -ῖν, -ᾶς</g>، </f> ضمير شخصي. <s><b>أنا</b>. <s n=\"(a)\">حالة الرفع تكون عادةً للتوكيد حين يُصرَّح بها فاعلاً، كما في <r v=\"Matt.3.11\"></r>، <r v=\"Mark.1.8\"></r>، <r v=\"Luke.3.16\"></r>، وفي مواضع أخرى. ولكن كثيرًا ما لا يظهر فيها توكيد، كما في <r v=\"Matt.10.16\"></r>، <r v=\"John.10.17\"></r>؛ <g>ἰδοὺ ἐ.</g> (= بالعبرية <h n=\"H2005\">הִנֵּנִי</h>، قارن <r v=\"1Kgs.3.8\"></r>)، <r v=\"Acts.9.10\"></r>؛ <g>ἐ.</g> (مثل العبرية <h n=\"H589\">אֲנִי</h>)، <b>أنا هو</b>، <r v=\"John.1.23\"></r>، <r v=\"Acts.7.32\"></r>. </s> <s n=\"(b)\">الصيغ الملحقة (انظر أعلاه) تُستعمل مع الأسماء والصفات والأفعال والظروف حيث لا توكيد: <g>ἐν τ. πατρί μου</g>، <r v=\"John.14.20\"></r>؛ <g>μου τ. λόγους</g>، <r v=\"Matt.7.24\"></r>؛ <g>ὀπίσω μου</g>، <r v=\"Matt.3.11\"></r>؛ <g>ἰσχυρότερός μου</g>، <r v=\"Matt.3.11\"></r>؛ <g>λέγει μοι</g>، <r v=\"Rev.5.5\"></r>؛ وكذلك مع حرف الجر <g>πρός</g>، كما في <r v=\"Mark.9.19\"></r>، وفي مواضع أخرى. أما الصيغ التامة (<g>ἐμοῦ</g>، إلخ) فتُستعمل مع حروف الجر الأخرى، مثل <g>δι' ἐμοῦ, ἐν ἐμοί, εἰς ἐμέ</g>، إلخ، وكذلك للتوكيد، كما في <r v=\"Luke.10.16\"></r>، <r v=\"John.7.23\"></r>، <r v=\"Mark.14.7\"></r>، وفي مواضع أخرى. </s> <s n=\"(c)\">كثيرًا ما تُستعمل صيغتا المضاف إليه <g>μου</g> و<g>ἡμῶν</g> بدل ضميري الملكية <g>ἐμός, ἡμέτερος: τ. λαόν μου</g>، <r v=\"Matt.2.6\"></r>؛ <g>μου τῂ ἀπιστιᾳ</g>، <r v=\"Mark.9.24\"></r>. </s> <s n=\"(d)\"><g>τί ἐμοὶ καὶ σοί</g> (= بالعبرية <h n=\"H4100\">וָלָךְ מַה־לִי</h>، <r v=\"Judg.11.12\"></r>، وفي مواضع أخرى)، أي <b>ما الذي بيننا من شركة؟ ما لي ولك؟</b>: <r v=\"Matt.8.29\"></r>، <r v=\"Mark.1.24\"></r> <r v=\"Mark.5.7\"></r>، <r v=\"Luke.8.28\"></r>، <r v=\"John.2.4\"></r>؛ <g>τί γάρ μοι</g>، <r v=\"1Cor.5.2\"></r>. </s> <s n=\"(e)\">التبادل بين <g>ἐγώ</g> و<g>ἡμεῖς</g>، يظهر في رسائل بولس.</s> <s n=\"(f)\"><g>κἀγώ</g> (= <g>καὶ ἐγώ</g>)، <b>وأنا، حتى أنا، أنا أيضًا</b>: <r v=\"Matt.2.8\"></r>، <r v=\"Luke.2.48\"></r>، <r v=\"John.6.56\"></r>، <r v=\"Rom.3.7\"></r>، <r v=\"1Cor.7.40\"></r>، وفي مواضع أخرى؛ <g>κἀγώ . . . καί</g>، <b>كلٌّ من... و</b>، <r v=\"John.7.28\"></r>.</s> </s>","en":"<f><o>ἐγώ</o>, gen, etc., <g>ἐμοῦ, ἐμοί, ἐμέ</g> (enclitic <g>μου, μοι, με</g>), pl. <g>ἡμεῖς, -ῶν, -ῖν, -ᾶς</g>, </f> pers. pron. <s><b>I</b>. <s n=\"(a)\">The nom. is usually emphatic, when expressed as subjc, as in <r v=\"Matt.3.11\"></r>, <r v=\"Mark.1.8\"></r>, <r v=\"Luke.3.16\"></r>, al. But often there is no apparent emphasis, as <r v=\"Matt.10.16\"></r>, <r v=\"John.10.17\"></r>; <g>ἰδοὺ ἐ.</g> (= Heb. <h n=\"H2005\">הִנֵּנִי</h>, cf. <r v=\"1Kgs.3.8\"></r>), <r v=\"Acts.9.10\"></r>; <g>ἐ.</g> (like Heb. <h n=\"H589\">אֲנִי</h>), <b>I am</b>, <r v=\"John.1.23\"></r>, <r v=\"Acts.7.32\"></r>. </s> <s n=\"(b)\">The enclitic forms (v. supr.) are used with nouns, adjectives, verbs, adverbs, where there is no emphasis: <g>ἐν τ. πατρί μου</g>, <r v=\"John.14.20\"></r>; <g>μου τ. λόγους</g>, <r v=\"Matt.7.24\"></r>; <g>ὀπίσω μου</g>, <r v=\"Matt.3.11\"></r>; <g>ἰσχυρότερός μου</g>, <r v=\"Matt.3.11\"></r>; <g>λέγει μοι</g>, <r v=\"Rev.5.5\"></r>; also with the prep. <g>πρός</g>, as <r v=\"Mark.9.19\"></r>, al. The full forms (<g>ἐμοῦ</g>, etc.) are used with the other prepositions, as <g>δι' ἐμοῦ, ἐν ἐμοί, εἰς ἐμέ</g>, etc., also for emphasis, as <r v=\"Luke.10.16\"></r>, <r v=\"John.7.23\"></r>, <r v=\"Mark.14.7\"></r>, al. </s> <s n=\"(c)\">The gen. <g>μου</g> and <g>ἡμῶν</g> are often used for the poss. pronouns <g>ἐμός, ἡμέτερος: τ. λαόν μου</g>, <r v=\"Matt.2.6\"></r>; <g>μου τῂ ἀπιστιᾳ</g>, <r v=\"Mark.9.24\"></r>. </s> <s n=\"(d)\"><g>τί ἐμοὶ καὶ σοί</g> ( = Heb. <h n=\"H4100\">וָלָךְ מַה־לִי</h>, <r v=\"Judg.11.12\"></r>, al.), i.e. <b>what have we in common</b>: <r v=\"Matt.8.29\"></r>, <r v=\"Mark.1.24\"></r> <r v=\"Mark.5.7\"></r>, <r v=\"Luke.8.28\"></r>, <r v=\"John.2.4\"></r>; <g>τί γάρ μοι</g>, <r v=\"1Cor.5.2\"></r>. </s> <s n=\"(e)\">The interchange of <g>ἐγώ</g> and <g>ἡμεῖς</g>, common in <g>π.</g>, appears in Pauline Epp. (v. M, <i>Pr.</i>, 86f., M, <i>Th.</i>, 131f.).</s> <s n=\"(f)\"><g>κἀγώ</g> (= <g>καὶ ἐγώ</g>, <b>and I, even I, I also</b>: <r v=\"Matt.2.8\"></r>, <r v=\"Luke.2.48\"></r>, <r v=\"John.6.56\"></r>, <r v=\"Rom.3.7\"></r>, <r v=\"1Cor.7.40\"></r>, al.; <g>κἀγώ . . . καί</g>, <b>both . . . and</b>, <r v=\"John.7.28\"></r>.</s> </s>"},"G1680":{"l":"ἐλπίς","o":53,"ar":"<f><o>ἐλπίς </o></f> <s><b>توقُّع، انتظار</b> (وفي العهد الجديد دائمًا عن الخير)، <b>رجاء</b>؛ </s> <s n=\"1.\">عن الرجاء عمومًا: <r v=\"2Cor.1.6\"></r>؛ مع المضاف إليه المفعولي، <r v=\"Acts.16.19\"></r>؛ مع المصدر المعرَّف بالأداة، <r v=\"Acts.27.20\"></r>، <r v=\"1Cor.9.10\"></r>؛ <g>παρ’ ἐλπίδα</g>، <r v=\"Rom.4.18\"></r>؛ <g>ἐπ’ ἐλπίδι</g>، <r v=\"1Cor.9.10\"></r>. </s> <s n=\"2.\">عن الرجاء الديني: <g>ἐπ’ ἐλπίδι</g>، <r v=\"Acts.2.26\"></r> <r v=\"Acts.26.6\"></r>، <r v=\"Rom.4.18\"></r> <r v=\"Rom.8.20\"></r>، <r v=\"Titus.1.2\"></r>؛ <g>τῇ ἐ. ἐσώθημεν</g>، <r v=\"Rom.8.24\"></r>؛ <g>κατ' ἐλπίδα ζωῆς αἰωνίου</g>، <r v=\"Titus.3.7\"></r>؛ عن رجاء إسرائيل المسيّاني، <r v=\"Acts.23.6\"></r> <r v=\"Acts.26.6\"></r>، <r v=\"Acts.26.7\"></r> <r v=\"Acts.28.20\"></r>؛ عن الرجاء المسيحي، <r v=\"Rom.5.2\"></r>، <r v=\"Rom.5.4\"></r>، <r v=\"Rom.5.5\"></r> <r v=\"Rom.12.12\"></r> <r v=\"Rom.15.4\"></r>، <r v=\"Rom.15.13\"></r>، <r v=\"1Cor.13.13\"></r>، <r v=\"2Thess.2.16\"></r>، <r v=\"Heb.3.6\"></r> <r v=\"Heb.6.11\"></r> <r v=\"Heb.7.19\"></r> <r v=\"Heb.10.23\"></r>، <r v=\"1Pet.1.3\"></r>، <r v=\"1Pet.1.21\"></r> <r v=\"1Pet.3.15\"></r>؛ مع المضاف إليه المفعولي، <r v=\"Rom.5.2\"></r>، <r v=\"Col.1.27\"></r>، <r v=\"1Thess.1.3\"></r> <r v=\"1Thess.5.8\"></r>، <r v=\"Titus.1.2\"></r>؛ مع المضاف إليه الدال على ما يقوم عليه الرجاء، <r v=\"Acts.26.6\"></r>، <r v=\"Eph.1.18\"></r> <r v=\"Eph.4.4\"></r>، <r v=\"Col.1.23\"></r>؛ <g>ὁ θεὸς τῆς ἐ.</g>، <r v=\"Rom.15.13\"></r>؛ <g>ἔχειν ἐ.</g>، <r v=\"Acts.24.15\"></r>، <r v=\"Rom.15.4\"></r>، <r v=\"2Cor.3.12\"></r> <r v=\"2Cor.10.15\"></r>، <r v=\"Eph.2.12\"></r>، <r v=\"1Thess.4.13\"></r>؛ يليه <g>ἐπί</g> مع القابل، <r v=\"1John.3.3\"></r>؛ <g>εἰς</g>، <r v=\"Acts.24.15\"></r>؛ <g>ὅτι</g>، <r v=\"Rom.8.20\"></r>، <r v=\"Phil.1.20\"></r>، <r v=\"Phil.1.21\"></r>. وكنايةً: </s> <s n=\"(a)\">عن صاحب الرجاء أو أساسه: <r v=\"1Thess.2.19\"></r>، <r v=\"1Tim.1.1\"></r>؛ مع المضاف إليه المفعولي، <r v=\"Col.1.27\"></r>؛ </s> <s n=\"(b)\">عن الشيء المرجوّ: <r v=\"Gal.5.5\"></r>، <r v=\"Col.1.5\"></r>، <r v=\"Titus.2.13\"></r>، <r v=\"Heb.6.18\"></r>.†</s>","en":"<f><o>ἐλπίς </o></f> <et> <e t=\"derivation\">(<g>ἑλ-</g>, <r v=\"Rom.8.20\"></r>, WH, v. Bl., § 4, 3; M, <i>Pr.</i>, 44), <g>-ίδος, ἡ</g> </e> <e t=\"septuagint\">[in LXX for <h n=\"H982\">בָּטַח</h> and its derivatives, <h n=\"H8615\">תִּקְוָה</h> (freq. in Jb), etc. ;] </e> </et> <s><b>expectation</b> (in cl., rarely of evil, mostly of good, and so always in NT), <b>hope</b>; </s> <s n=\"1.\">of hope in general: <r v=\"2Cor.1.6\"></r>; c. gen. obj., <r v=\"Acts.16.19\"></r>; art. inf., <r v=\"Acts.27.20\"></r>, <r v=\"1Cor.9.10\"></r>; <g>παρ’ ἐλπίδα</g>, <r v=\"Rom.4.18\"></r>; <g>ἐπ’ ἐλπίδι</g>, <r v=\"1Cor.9.10\"></r>. </s> <s n=\"2.\">Of religious hope: <g>ἐπ’ ἐλπίδι</g>, <r v=\"Acts.2.26\"></r> <r v=\"Acts.26.6\"></r>, <r v=\"Rom.4.18\"></r> <r v=\"Rom.8.20\"></r>, <r v=\"Titus.1.2\"></r>; <g>τῇ ἐ. ἐσώθημεν</g>, <r v=\"Rom.8.24\"></r>; <g>κατ' ἐλπίδα ζωῆς αἰωνίου</g>, <r v=\"Titus.3.7\"></r>; of the Messianic hope of Israel, <r v=\"Acts.23.6\"></r> <r v=\"Acts.26.6\"></r>, <r v=\"Acts.26.7\"></r> <r v=\"Acts.28.20\"></r>; of Christian hope, <r v=\"Rom.5.2\"></r>, <r v=\"Rom.5.4\"></r>, <r v=\"Rom.5.5\"></r> <r v=\"Rom.12.12\"></r> <r v=\"Rom.15.4\"></r>, <r v=\"Rom.15.13\"></r>, <r v=\"1Cor.13.13\"></r>, <r v=\"2Thess.2.16\"></r>, <r v=\"Heb.3.6\"></r> <r v=\"Heb.6.11\"></r> <r v=\"Heb.7.19\"></r> <r v=\"Heb.10.23\"></r>, <r v=\"1Pet.1.3\"></r>, <r v=\"1Pet.1.21\"></r> <r v=\"1Pet.3.15\"></r>; c. gen. obj., <r v=\"Rom.5.2\"></r>, <r v=\"Col.1.27\"></r>, <r v=\"1Thess.1.3\"></r> <r v=\"1Thess.5.8\"></r>, <r v=\"Titus.1.2\"></r>; c. gen. of that on which the hope is based, <r v=\"Acts.26.6\"></r>, <r v=\"Eph.1.18\"></r> <r v=\"Eph.4.4\"></r>, <r v=\"Col.1.23\"></r>; <g>ὁ θεὸς τῆς ἐ.</g>, <r v=\"Rom.15.13\"></r>; <g>ἔχειν ἐ.</g> (= cl. <g>ἐλπίζειν</g>), <r v=\"Acts.24.15\"></r>, <r v=\"Rom.15.4\"></r>, <r v=\"2Cor.3.12\"></r> <r v=\"2Cor.10.15\"></r>, <r v=\"Eph.2.12\"></r>, <r v=\"1Thess.4.13\"></r>; seq. <g>ἐπί</g>, c. dat., <r v=\"1John.3.3\"></r>; <g>εἰς</g>, <r v=\"Acts.24.15\"></r>; <g>ὅτι</g>, <r v=\"Rom.8.20\"></r>, <r v=\"Phil.1.20\"></r>, <r v=\"Phil.1.21\"></r>. Meton., </s> <s n=\"(a)\">of the author or ground of hope (cl.): <r v=\"1Thess.2.19\"></r>, <r v=\"1Tim.1.1\"></r>; c. gen. obj., <r v=\"Col.1.27\"></r>; </s> <s n=\"(b)\">of the thing hoped for: <r v=\"Gal.5.5\"></r>, <r v=\"Col.1.5\"></r>, <r v=\"Titus.2.13\"></r>, <r v=\"Heb.6.18\"></r> (Cremer, 252, 712).†</s>"},"G1607":{"l":"ἐκπορεύω","o":33,"ar":"<f><o>ἐκ-πορεύω </o></f> <s><b>يُخرِج، يجعله يخرج</b>؛ في المبني للمجهول والصيغة الوسطى، <b>يخرج</b>: <r v=\"Luke.3.7\"></r>، <r v=\"Acts.25.4\"></r>؛ عن الشياطين الخارجة من الممسوس، <r v=\"Matt.17.21\"></r>، <r v=\"Acts.19.12\"></r>؛ عن الفضلات، <r v=\"Mark.7.19\"></r>؛ يليه <g>ἀπό</g>، <r v=\"Matt.20.29\"></r>، <r v=\"Mark.10.46\"></r>؛ <g>ἐκ</g>، <r v=\"Mark.13.1\"></r> (عن قيامة الأموات، <r v=\"John.5.29\"></r>)؛ <g>ἐκεῖθεν</g>، <r v=\"Mark.6.11\"></r>؛ <g>ἔξω</g>، <r v=\"Mark.11.19\"></r>؛ <g>είς</g>، <r v=\"Mark.10.17\"></r>، <r v=\"John.5.29\"></r>؛ <g>ἐπί</g>، مع منصوب الشخص، <r v=\"Rev.16.14\"></r>؛ <g>πρός</g>، مع منصوب الشخص، <r v=\"Matt.3.5\"></r>، <r v=\"Mark.1.5\"></r>؛ <g>εἰσπορ-</g> (انظره) <g>καὶ ἐ.</g>، <r v=\"Acts.9.28\"></r>؛ مجازيًا، <b>يخرج، يصدر، ينبثق</b>: عن المشاعر ونحوها، <r v=\"Mark.7.23\"></r>؛ يليه <g>ἐκ</g>، <r v=\"Matt.15.11\"></r>، <r v=\"Matt.15.18\"></r> <r v=\"Mark.7.15\"></r>، <r v=\"Mark.7.20\"></r>، <r v=\"Mark.7.21\"></r>، <r v=\"Luke.4.22\"></r>، <r v=\"Eph.4.29\"></r>؛ <g>ῥῆμα</g>، يليه <g>διά</g>، <r v=\"Matt.4.4\"></r> <i>(السبعينية)</i>؛ عن البروق واللهيب، <r v=\"Rev.4.5\"></r> <r v=\"Rev.9.17\"></r>، <r v=\"Rev.9.18\"></r> <r v=\"Rev.11.5\"></r>؛ عن نهر، <r v=\"Rev.22.1\"></r>؛ عن سيف، <r v=\"Rev.1.16\"></r> <r v=\"Rev.19.15\"></r>؛ عن خبر يذيع، يليه <g>εἰς</g>، <r v=\"Luke.4.37\"></r>؛ عن الروح القدس، يليه <g>παρά</g>، <r v=\"John.15.26\"></r>.†</s>","en":"<f><o>ἐκ-πορεύω </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3318\">יָצָא</h> ;] </e> </et> <s><b>to make to go out</b>; pass. and mid., <b>to go forth</b>: <r v=\"Luke.3.7\"></r>, <r v=\"Acts.25.4\"></r>; of demons leaving one possessed, <r v=\"Matt.17.21\"></r> (WH om.), <r v=\"Acts.19.12\"></r>; of excrement, <r v=\"Mark.7.19\"></r>; seq. <g>ἀπό</g>, <r v=\"Matt.20.29\"></r>, <r v=\"Mark.10.46\"></r>; <g>ἐκ</g>, <r v=\"Mark.13.1\"></r> (of the dead rising, <r v=\"John.5.29\"></r>); <g>ἐκεῖθεν</g>, <r v=\"Mark.6.11\"></r>; <g>ἔξω</g>, <r v=\"Mark.11.19\"></r>; <g>είς</g>, <r v=\"Mark.10.17\"></r>, <r v=\"John.5.29\"></r>; <g>ἐπί</g>, c. acc pers., <r v=\"Rev.16.14\"></r>; <g>πρός</g>, c. acc pers., <r v=\"Matt.3.5\"></r>, <r v=\"Mark.1.5\"></r>; <g>εἰσπορ-</g> (q.v.) <g>καὶ ἐ.</g>, <r v=\"Acts.9.28\"></r>; metaph., <b>to come forth, proceed</b>: of feelings, etc., <r v=\"Mark.7.23\"></r>; seq. <g>ἐκ</g>, <r v=\"Matt.15.11\"></r>, <r v=\"Matt.15.18\"></r> <r v=\"Mark.7.15\"></r>, <r v=\"Mark.7.20\"></r>, <r v=\"Mark.7.21\"></r>, <r v=\"Luke.4.22\"></r>, <r v=\"Eph.4.29\"></r>; <g>ῥῆμα</g>, seq. <g>διά</g>, <r v=\"Matt.4.4\"></r> <i>(LXX)</i>; of lightning and flame, <r v=\"Rev.4.5\"></r> <r v=\"Rev.9.17\"></r>, <r v=\"Rev.9.18\"></r> <r v=\"Rev.11.5\"></r>; a river, <r v=\"Rev.22.1\"></r>; a sword, <r v=\"Rev.1.16\"></r> <r v=\"Rev.19.15\"></r>; a rumour, seq. <g>εἰς</g>, <r v=\"Luke.4.37\"></r>; of the Holy Spirit, seq. <g>παρά</g>, <r v=\"John.15.26\"></r>.†</s>"},"G1651":{"l":"ἐλέγχω","o":17,"ar":"<f><o>ἐλέγχω</o> </f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>يعامله بازدراء</b>. </s> <s n=\"2.\"><b>يُبكِّت، يُثبت عليه الذنب</b>: مع المنصوب، <r v=\"Matt.18.15\"></r>، <r v=\"Titus.1.9\"></r>؛ يليه <g>περί</g>، <r v=\"John.8.46\"></r> <r v=\"John.16.8\"></r>، <r v=\"Jude.1.15\"></r>؛ في المبني للمجهول، <r v=\"Jas.2.9\"></r>. </s> <s n=\"3.\"><b>يوبّخ، ينتهر</b>: <r v=\"1Tim.5.20\"></r>، <r v=\"2Tim.4.2\"></r>، <r v=\"Titus.1.13\"></r> <r v=\"Titus.2.15\"></r>، <r v=\"Rev.3.19\"></r>؛ في المبني للمجهول، يليه <g>περί</g>، <r v=\"Luke.3.19\"></r>؛ <g>ὑπό</g>، <r v=\"Heb.12.5\"></r> <i>(السبعينية)</i>. </s> <s n=\"4.\"><b>يفضح، يكشف</b>: <r v=\"Eph.5.11\"></r>؛ في المبني للمجهول، <r v=\"John.3.20\"></r>، <r v=\"1Cor.14.24\"></r>، <r v=\"Eph.5.13\"></r> (قارن <r v=\"Eph.5.11\"></r>؛ قارن <g>ἐξ-</g>، <g>δια-κατ-ελέγχομαι</g>).†</s>","en":"<f><o>ἐλέγχω</o> </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3198\">יָכַח</h> hi. ;] </e> </et> <s n=\"1.\">in Hom., <b>to treat with contempt</b>. </s> <s n=\"2.\"><b>to convict</b>: c. acc, <r v=\"Matt.18.15\"></r> (RV,<b> show him his fault</b>), <r v=\"Titus.1.9\"></r>; seq. <g>περί</g>, <r v=\"John.8.46\"></r> <r v=\"John.16.8\"></r>, <r v=\"Jude.1.15\"></r>; pass., <r v=\"Jas.2.9\"></r>. </s> <s n=\"3.\"><b>to reprove, rebuke</b>: <r v=\"1Tim.5.20\"></r>, <r v=\"2Tim.4.2\"></r>, <r v=\"Titus.1.13\"></r> <r v=\"Titus.2.15\"></r>, <r v=\"Rev.3.19\"></r>; pass., seq. <g>περί</g>, <r v=\"Luke.3.19\"></r>; <g>ὑπό</g>, <r v=\"Heb.12.5\"></r> <i>(LXX)</i>. </s> <s n=\"4.\"><b>to expose</b>: <r v=\"Eph.5.11\"></r>; pass., <r v=\"John.3.20\"></r>, <r v=\"1Cor.14.24\"></r> (RV <b>reprove</b>, mg. <b>convict</b>), <r v=\"Eph.5.13\"></r> (RV, as 1 Co, l.c., of. AR on <r v=\"Eph.5.11\"></r>; MM, <i>Exp.</i>, xii; cf. <g>ἐξ-</g>, <g>δια-κατ-ελέγχομαι</g>).†</s> <sy><i>SYN.</i>: <g>ἐπιτιμῶ</g>, expressing simply rebuke, which may be un­deserved (<r v=\"Matt.16.22\"></r>) or ineffectual (<r v=\"Luke.23.40\"></r>), while <g>ἐλ.</g> implies rebuke which brings conviction (v. Tr., <i>Syn.</i>, § iv) </sy>"},"G1600":{"l":"ἐκπετάννυμι","o":1,"ar":"<f><o>ἐκ-πετάννυμι </o></f> <s><b>يبسط</b> (كالشراع)، <b>يمدّ</b>: <r v=\"Rom.10.21\"></r><i>(السبعينية)</i>.†</s>","en":"<f><o>ἐκ-πετάννυμι </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6566\">פָּרַשׂ</h>, as <r v=\"Isa.65.2\"></r> (hithp.) ;]</e> </et> <s><b>to spread out</b> (as a sail), <b>stretch forth</b>: <r v=\"Rom.10.21\"></r><i>(LXX)</i>.†</s>"},"G1650":{"l":"ἐλεγμός","o":1,"ar":"<f>† <o>ἐλεγμός</o>، <g>-οῦ, ὁ</g></f> <s><b>توبيخ</b>: <r v=\"2Tim.3.16\"></r>.†</s>","en":"<f>† <o>ἐλεγμός</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>ἐλέγχω</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Ps.38.14\"></r> <r v=\"Ps.39.11\"></r> (<h n=\"H8433\">תּוֹכֵחָה</h>), <r v=\"Sir.20.29\"></r> <r v=\"Sir.21.6\"></r> <r v=\"Sir.41.4\"></r>, al. ;] </e> </et> <s><b>reproof</b>: <r v=\"2Tim.3.16\"></r>.†</s>"},"G1636":{"l":"ἐλαία","o":13,"ar":"<f><o>ἐλαία</o></f> <s n=\"1.\"><b>شجرة زيتون</b>: <r v=\"Rom.11.17\"></r>، <r v=\"Rom.11.24\"></r>، <r v=\"Rev.11.4\"></r>؛ <g>τ. ὄρος τῶν ἐ.</g> (<h n=\"H2022\">הַר הַוֵּתִים</h>، <r v=\"Zech.14.4\"></r>): <b>جبل الزيتون</b>: <r v=\"Matt.21.1\"></r>، <r v=\"Matt.24.3\"></r>، <r v=\"Matt.26.30\"></r>، <r v=\"Mark.11.1\"></r>، <r v=\"Mark.13.3\"></r>، <r v=\"Mark.14.26\"></r>، <r v=\"Luke.19.37\"></r>، <r v=\"Luke.22.39\"></r>؛ <g>τὸ καλούμενον ἐ.</g>: <r v=\"Luke.19.29\"></r>، <r v=\"Luke.21.37\"></r>. </s> <s n=\"2.\"><b>زيتونة</b> (ثمرة الزيتون): <r v=\"Jas.3.12\"></r>.†</s>","en":"<f><o>ἐλαία</o></f> <et> <e t=\"derivation\">(Attic, <g>ἐλάα</g>), <g>-ας, ἡ</g> </e> <e t=\"septuagint\">[in LXX for <h n=\"H2132\">זַיִת</h> ;] </e> </et> <s n=\"1.\"><b>an olive tree</b>: <r v=\"Rom.11.17\"></r>, <r v=\"Rom.11.24\"></r>, <r v=\"Rev.11.4\"></r>; <g>τ. ὄρος τῶν ἐ.</g> (<h n=\"H2022\">הַר הַוֵּתִים</h>, <r v=\"Zech.14.4\"></r>), <b>the Mount of Olives</b>: <r v=\"Matt.21.1\"></r> <r v=\"Matt.24.3\"></r> <r v=\"Matt.26.30\"></r>, <r v=\"Mark.11.1\"></r> <r v=\"Mark.13.3\"></r> <r v=\"Mark.14.26\"></r>, <r v=\"Luke.19.37\"></r> <r v=\"Luke.22.39\"></r>; <g>τὸ καλούμενον ἐ.</g> (T, <g>ἐλαιών</g>, q.v.), <r v=\"Luke.19.29\"></r> <r v=\"Luke.21.37\"></r>. </s> <s n=\"2.\"><b>an olive</b> (Aristoph.): <r v=\"Jas.3.12\"></r>.†</s>"},"G1624":{"l":"ἐκτρέπω","o":5,"ar":"<f><o>ἐκ-τρέπω </o></f> <s><b>حوّل عن الطريق، أمال</b>، مع المنصوب. المبني للمجهول بمعنى الصيغة الوسطى، لازمًا: <b>انحرف، مال عن</b>: <r v=\"Heb.12.13\"></r>؛ مجازيًا، يليه <g>εἰς</g>: <r v=\"1Tim.1.6\"></r>؛ <g>ἐπί</g>: <r v=\"2Tim.4.4\"></r>؛ <g>ὀπίσω</g>: <r v=\"1Tim.5.15\"></r>؛ مع المنصوب: <b>تجنّب، أعرض عن</b>: <r v=\"1Tim.6.20\"></r>.†</s>","en":"<f><o>ἐκ-τρέπω </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H2015\">הָפַךְ</h>, <r v=\"Amos.5.8\"></r> * ;] </e> </et> <s><b>to turn out of the course, turn aside</b>, c. acc Pass., with middle sense, intrans., <b>to turn aside</b>: <r v=\"Heb.12.13\"></r> (R, txt., for <b>be put out of joint</b>, R, mg., v. Thayer, s.v. Westc., in l); fig., seq. <g>εἰς</g>, <r v=\"1Tim.1.6\"></r>; <g>ἐπί</g>, <r v=\"2Tim.4.4\"></r>; <g>ὀπίσω</g>, <r v=\"1Tim.5.15\"></r>; c. acc, <b>to shun, avoid</b>: <r v=\"1Tim.6.20\"></r>.†</s>"},"G1635":{"l":"ἑκών","o":2,"ar":"<f><o>ἑκών</o>، <g>-οῦσα, -όν </g></f> <s><b>راغب، طوعًا (بإرادته)</b>: <r v=\"Rom.8.20\"></r>، <r v=\"1Cor.9.17\"></r>.†</s>","en":"<f><o>ἑκών</o>, <g>-οῦσα, -όν </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Exod.21.13\"></r>, <r v=\"Job.36.19\"></r> * ;] </e> </et> <s><b>willing, of one's own free will</b>: <r v=\"Rom.8.20\"></r>, <r v=\"1Cor.9.17\"></r> (Cremer, 246).†</s>"},"G1622":{"l":"ἕκτος","o":14,"ar":"<f><o>ἕκτος</o>، <g>-η, -ον </g></f> <s><b>السادس</b>: <r v=\"Matt.20.5\"></r>، وفي مواضع أخرى </s>","en":"<f><o>ἕκτος</o>, <g>-η, -ον </g></f> <s><b>the sixth</b>: <r v=\"Matt.20.5\"></r>, al </s>"},"G1698":{"l":"ἐγώ","o":2572,"ar":"<f><o>ἐγώ</o>، حالة الجر إلخ: <g>ἐμοῦ, ἐμοί, ἐμέ</g> (والصيغ الملحقة <g>μου, μοι, με</g>)، الجمع: <g>ἡμεῖς, -ῶν, -ῖν, -ᾶς</g>، </f> ضمير شخصي <s><b>أنا</b>. <s n=\"(a)\">حالة الرفع تأتي عادةً للتوكيد حين يُذكر الضمير فاعلاً، كما في <r v=\"Matt.3.11\"></r>، <r v=\"Mark.1.8\"></r>، <r v=\"Luke.3.16\"></r>، وفي مواضع أخرى. لكن كثيرًا ما لا يظهر توكيد، مثل <r v=\"Matt.10.16\"></r>، <r v=\"John.10.17\"></r>؛ <g>ἰδοὺ ἐ.</g> (= العبرية <h n=\"H2005\">הִנֵּנִי</h>، قارن <r v=\"1Kgs.3.8\"></r>)، <r v=\"Acts.9.10\"></r>؛ <g>ἐ.</g> (مثل العبرية <h n=\"H589\">אֲנִי</h>)، <b>أنا هو</b>، <r v=\"John.1.23\"></r>، <r v=\"Acts.7.32\"></r>. </s> <s n=\"(b)\">الصيغ الملحقة (انظر أعلاه) تُستعمل مع الأسماء والصفات والأفعال والظروف حيث لا توكيد: <g>ἐν τ. πατρί μου</g>، <r v=\"John.14.20\"></r>؛ <g>μου τ. λόγους</g>، <r v=\"Matt.7.24\"></r>؛ <g>ὀπίσω μου</g>، <r v=\"Matt.3.11\"></r>؛ <g>ἰσχυρότερός μου</g>، <r v=\"Matt.3.11\"></r>؛ <g>λέγει μοι</g>، <r v=\"Rev.5.5\"></r>؛ وأيضًا مع حرف الجر <g>πρός</g>، مثل <r v=\"Mark.9.19\"></r>، وفي مواضع أخرى. أما الصيغ الكاملة (<g>ἐμοῦ</g> إلخ) فتُستعمل مع حروف الجر الأخرى، مثل <g>δι' ἐμοῦ, ἐν ἐμοί, εἰς ἐμέ</g> إلخ، وكذلك للتوكيد، مثل <r v=\"Luke.10.16\"></r>، <r v=\"John.7.23\"></r>، <r v=\"Mark.14.7\"></r>، وفي مواضع أخرى. </s> <s n=\"(c)\">كثيرًا ما تُستعمل حالة الجر <g>μου</g> و<g>ἡμῶν</g> بدل ضميري الملكية <g>ἐμός, ἡμέτερος: τ. λαόν μου</g>، <r v=\"Matt.2.6\"></r>؛ <g>μου τῂ ἀπιστιᾳ</g>، <r v=\"Mark.9.24\"></r>. </s> <s n=\"(d)\"><g>τί ἐμοὶ καὶ σοί</g> (= العبرية <h n=\"H4100\">וָלָךְ מַה־לִי</h>، <r v=\"Judg.11.12\"></r>، وفي مواضع أخرى)، أي <b>ما لنا ولك؟</b> (ما الشأن المشترك بيننا؟): <r v=\"Matt.8.29\"></r>، <r v=\"Mark.1.24\"></r>، <r v=\"Mark.5.7\"></r>، <r v=\"Luke.8.28\"></r>، <r v=\"John.2.4\"></r>؛ <g>τί γάρ μοι</g>، <r v=\"1Cor.5.2\"></r>. </s> <s n=\"(e)\">التبادل بين <g>ἐγώ</g> و<g>ἡμεῖς</g>، الشائع في <g>π.</g>، يظهر في رسائل بولس.</s> <s n=\"(f)\"><g>κἀγώ</g> (= <g>καὶ ἐγώ</g>)، <b>وأنا، أنا أيضًا، وأنا كذلك</b>: <r v=\"Matt.2.8\"></r>، <r v=\"Luke.2.48\"></r>، <r v=\"John.6.56\"></r>، <r v=\"Rom.3.7\"></r>، <r v=\"1Cor.7.40\"></r>، وفي مواضع أخرى؛ <g>κἀγώ . . . καί</g>، <b>كلٌّ من . . . و</b>، <r v=\"John.7.28\"></r>.</s> </s>","en":"<f><o>ἐγώ</o>, gen, etc., <g>ἐμοῦ, ἐμοί, ἐμέ</g> (enclitic <g>μου, μοι, με</g>), pl. <g>ἡμεῖς, -ῶν, -ῖν, -ᾶς</g>, </f> pers. pron. <s><b>I</b>. <s n=\"(a)\">The nom. is usually emphatic, when expressed as subjc, as in <r v=\"Matt.3.11\"></r>, <r v=\"Mark.1.8\"></r>, <r v=\"Luke.3.16\"></r>, al. But often there is no apparent emphasis, as <r v=\"Matt.10.16\"></r>, <r v=\"John.10.17\"></r>; <g>ἰδοὺ ἐ.</g> (= Heb. <h n=\"H2005\">הִנֵּנִי</h>, cf. <r v=\"1Kgs.3.8\"></r>), <r v=\"Acts.9.10\"></r>; <g>ἐ.</g> (like Heb. <h n=\"H589\">אֲנִי</h>), <b>I am</b>, <r v=\"John.1.23\"></r>, <r v=\"Acts.7.32\"></r>. </s> <s n=\"(b)\">The enclitic forms (v. supr.) are used with nouns, adjectives, verbs, adverbs, where there is no emphasis: <g>ἐν τ. πατρί μου</g>, <r v=\"John.14.20\"></r>; <g>μου τ. λόγους</g>, <r v=\"Matt.7.24\"></r>; <g>ὀπίσω μου</g>, <r v=\"Matt.3.11\"></r>; <g>ἰσχυρότερός μου</g>, <r v=\"Matt.3.11\"></r>; <g>λέγει μοι</g>, <r v=\"Rev.5.5\"></r>; also with the prep. <g>πρός</g>, as <r v=\"Mark.9.19\"></r>, al. The full forms (<g>ἐμοῦ</g>, etc.) are used with the other prepositions, as <g>δι' ἐμοῦ, ἐν ἐμοί, εἰς ἐμέ</g>, etc., also for emphasis, as <r v=\"Luke.10.16\"></r>, <r v=\"John.7.23\"></r>, <r v=\"Mark.14.7\"></r>, al. </s> <s n=\"(c)\">The gen. <g>μου</g> and <g>ἡμῶν</g> are often used for the poss. pronouns <g>ἐμός, ἡμέτερος: τ. λαόν μου</g>, <r v=\"Matt.2.6\"></r>; <g>μου τῂ ἀπιστιᾳ</g>, <r v=\"Mark.9.24\"></r>. </s> <s n=\"(d)\"><g>τί ἐμοὶ καὶ σοί</g> ( = Heb. <h n=\"H4100\">וָלָךְ מַה־לִי</h>, <r v=\"Judg.11.12\"></r>, al.), i.e. <b>what have we in common</b>: <r v=\"Matt.8.29\"></r>, <r v=\"Mark.1.24\"></r> <r v=\"Mark.5.7\"></r>, <r v=\"Luke.8.28\"></r>, <r v=\"John.2.4\"></r>; <g>τί γάρ μοι</g>, <r v=\"1Cor.5.2\"></r>. </s> <s n=\"(e)\">The interchange of <g>ἐγώ</g> and <g>ἡμεῖς</g>, common in <g>π.</g>, appears in Pauline Epp. (v. M, <i>Pr.</i>, 86f., M, <i>Th.</i>, 131f.).</s> <s n=\"(f)\"><g>κἀγώ</g> (= <g>καὶ ἐγώ</g>, <b>and I, even I, I also</b>: <r v=\"Matt.2.8\"></r>, <r v=\"Luke.2.48\"></r>, <r v=\"John.6.56\"></r>, <r v=\"Rom.3.7\"></r>, <r v=\"1Cor.7.40\"></r>, al.; <g>κἀγώ . . . καί</g>, <b>both . . . and</b>, <r v=\"John.7.28\"></r>.</s> </s>"},"G1629":{"l":"ἐκφοβέω","o":1,"ar":"<f><o>ἐκ-φοβέω</o>، <g>-ῶ </g></f> <s><b>أفزع، أرعب، أرهب</b>: مع المنصوب للشخص، <r v=\"2Cor.10.9\"></r>.†</s>","en":"<f><o>ἐκ-φοβέω</o>, <g>-ῶ </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2730\">חָרֵד</h> hi. ;] </e> </et> <s><b>to frighten away, terrif</b>y: c. acc pers., <r v=\"2Cor.10.9\"></r>.†</s>"},"G1644":{"l":"ἐλαφρία","o":1,"ar":"<f>*† <o>ἐλαφρία</o>، <g>-ας, ἡ </g></f> <s><b>خفّة، طيش</b>: <r v=\"2Cor.1.17\"></r>.†</s>","en":"<f>*† <o>ἐλαφρία</o>, <g>-ας, ἡ </g></f> <s><b>lightness, levity</b>: <r v=\"2Cor.1.17\"></r>.†</s>"},"G1687":{"l":"ἐμβατεύω","o":1,"ar":"<f><o>ἐμβατεύω </o></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>يدخل</b> أو <b>يطأ</b>، ومن ثمّ </s> <s n=\"(a)\"><b>يرتاد، يتردد على، يسكن في</b>؛ مجازيًا، <r v=\"Col.2.18\"></r> (بمعنى <b>متداخلاً في</b>، أو: متمسكًا بـ)؛ </s> <s n=\"(b)\"><b>يغزو، يقتحم</b> (في السبعينية؛ ومجازيًا في موضع كولوسي نفسه). </s> <s n=\"2.\">في السبعينية: <b>يدخل إلى، يستولي على، يمتلك</b>؛ وفي قراءة هذا الموضع وتفسيره صعوبات (قارن <g>κενεμβ.</g>).†</s>","en":"<f><o>ἐμβατεύω </o></f> <et> <e t=\"septuagint\">[in LXX: c. acc, <r v=\"Josh.19.49\"></r> (<h n=\"H5157\">נָחַל</h>, <r v=\"Josh.19.51\"></r> (<h n=\"H2505\">חָלַק</h> pi.); seq. <g>εἰς</g>, <r v=\"1Macc.12.25\"></r> <r v=\"1Macc.13.20\"></r> <r v=\"1Macc.14.31\"></r> <r v=\"1Macc.15.40\"></r>; metaph., <r v=\"2Macc.2.30\"></r> * ;] </e> <e t=\"derivation\">(&lt; <g>ἐμβάτης</g> &lt; <g>ἐμβαίνω</g>) </e> </et> <s n=\"1.\"><b>to step in</b> or <b>on</b> (Soph.), hence </s> <s n=\"(a)\"><b>to frequent, haunt, dwell in</b> (Æsch., Eur.); metaph., <r v=\"Col.2.18\"></r> (<b>dwelling in</b>, R, txt.; taking, R, mg.); </s> <s n=\"(b)\"><b>to invade</b> (1Mac, ll c.; metaph., Col, l.c.). </s> <s n=\"2.\"><b>to enter on, come into possession of</b> (Eur., Dem.; LXX, Jos, ll. c.); on the difficulties of reading and interpretation in this passage, v. Lft, Col., 194 f., 252; <i>ICC</i>, 268 ff.; Field, <i>Notes</i>, 197; Milligan, <i>NTD</i>, 177; and for exx. from <g>π.</g>, MM, <i>Exp.</i>, xii (cf. <g>κενεμβ.</g>).†</s>"},"G1601":{"l":"ἐκπίπτω","o":10,"ar":"<f><o>ἐκ-πίπτω </o></f> <s><b>يسقط من، يقع عن</b>: يليه <g>ἐκ τ. χειρῶν</g>، <r v=\"Acts.12.7\"></r>؛ مطلقًا، <r v=\"Acts.27.32\"></r>؛ عن ذبول الزهر (كما في السبعينية)، <r v=\"Jas.1.11\"></r>، <r v=\"1Pet.1.24\"></r> <i>(السبعينية)</i>؛ عن الملاحين المنحرفين عن مسارهم المستقيم (يُدفعون، ينجرفون)، <r v=\"Acts.27.17\"></r>، <r v=\"Acts.27.26\"></r>، <r v=\"Acts.27.29\"></r>. مجازيًا: مع مضاف إليه الشيء (يسقط من)، <r v=\"Gal.5.4\"></r>، <r v=\"2Pet.3.17\"></r>؛ مطلقًا: <b>يسقط عن مكانه، يخيب، يسقط (فلا يتم)</b>: <r v=\"Rom.9.6\"></r>.†</s>","en":"<f><o>ἐκ-πίπτω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Isa.40.8\"></r> <r v=\"Isa.28.1\"></r>, <r v=\"Isa.28.4\"></r> (<h n=\"H1892\">הֶבֶל</h>), <r v=\"Job.14.2\"></r> (<h n=\"H4448\">מָלַל</h>, v. RV. mg), <r v=\"Job.15.30\"></r> (<h n=\"H5493\">סוּר</h>), <r v=\"Job.15.33\"></r> (<h n=\"H7993\">שָׁלַךְ</h> hi.), etc. ;] </e> </et> <s><b>to fall out of, fall from, fall off</b>: seq. <g>ἐκ τ. χειρῶν</g>, <r v=\"Acts.12.7\"></r>; absol., <r v=\"Acts.27.32\"></r>; of the withering of flowers (as LXX, ll c.), <r v=\"Jas.1.11\"></r>, <r v=\"1Pet.1.24\"></r> <i>(LXX)</i>; of navigators falling off from a straight course, <r v=\"Acts.27.17\"></r>, <r v=\"Acts.27.26\"></r>, <r v=\"Acts.27.29\"></r>. Metaph., c. gen. rei: <r v=\"Gal.5.4\"></r>, <r v=\"2Pet.3.17\"></r>; absol., <b>fall from its place, fail, perish</b>: <r v=\"Rom.9.6\"></r>.†</s>"},"G1612":{"l":"ἐκστρέφω","o":1,"ar":"<f><o>ἐκ-στρέφω </o></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>يُخرج بالقلب، يقلب إلى الخارج</b>. </s> <s n=\"2.\"><b>يقلب رأسًا على عقب</b>؛ مجازيًا: <b>يغيّر كليًّا، ينحرف، يفسد</b>: <r v=\"Titus.3.11\"></r>.†</s>","en":"<f><o>ἐκ-στρέφω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Deut.32.20\"></r>, <r v=\"Amos.6.13\"></r> <r v=\"Ezek.16.34\"></r> A (<h n=\"H2015\">הָפַךְ</h>), <r v=\"Zech.11.16\"></r> (<h n=\"H6561\">פָּרַק</h> pi.), <r v=\"Ezek.13.20\"></r> (<h n=\"H6679\">צוּד</h> pil.)* ;] </e> </et> <s n=\"1.\"><b>to turn out of</b> (Hom.). </s> <s n=\"2.\"><b>to turn inside out</b>; metaph., <b>to change entirely, pervert</b> (Aristoph.): <r v=\"Titus.3.11\"></r>.†</s>"},"G1652":{"l":"ἐλεεινός","o":2,"ar":"<f><o>ἐλεεινός</o>، <g>-ή, -όν</g></f> <s><b>يُرثى له، بائس، شقيّ</b>: <r v=\"Rev.3.17\"></r>؛ صيغة التفضيل، <r v=\"1Cor.15.19\"></r>.†</s>","en":"<f><o>ἐλεεινός</o>, <g>-ή, -όν</g></f> <et> <e t=\"derivation\">(&lt; <g>ἔλεος</g> in Re, l.c., WH have the Attic poëtic form, <g>ἐλεινός</g>), </e> </et> <s><b>pitiable, miserable</b>: <r v=\"Rev.3.17\"></r>; comparat., <r v=\"1Cor.15.19\"></r>.†</s>"},"G1609":{"l":"ἐκπτύω","o":1,"ar":"<f>* <o>ἐκ-πτύω </o></f> <s n=\"1.\"><b>يبصق، يلفظ</b>. </s> <s n=\"2.\"><b>يبصق على أحد اشمئزازًا، يكره، يمقت</b> (= <g>ἀποπτ-, καταπτ-</g> في الكلاسيكية): <r v=\"Gal.4.14\"></r>.†</s>","en":"<f>* <o>ἐκ-πτύω </o></f> <s n=\"1.\"><b>to spit out</b>. </s> <s n=\"2.\"><b>to spit at in disgust, to abominate, loathe</b> (= cl. <g>ἀποπτ-, καταπτ-</g>): <r v=\"Gal.4.14\"></r>.†</s>"},"G1641":{"l":"ἐλαττονέω","o":1,"ar":"<f>† <o>ἐλαττονέω</o>، <g>-ῶ</g></f> <s><b>يكون أقلّ، ينقص</b> (الترجمة المنقحة:<b> لم ينقص</b>): <r v=\"2Cor.8.15\"></r> <i>(السبعينية)</i> (كلمة نادرة).†</s>","en":"<f>† <o>ἐλαττονέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>ἔλαττον</g>), </e> <e t=\"septuagint\">[in LXX (with <g>-όω</g>) chiefly for <h n=\"H2637\">חָסֵר</h> ;] </e> </et> <s><b>to be less</b> (RV,<b> had no lack</b>): <r v=\"2Cor.8.15\"></r> <i>(LXX)</i> (a rare word; cf. MM, <i>Exp.</i>, xii).†</s>"},"G1646":{"l":"ἐλάχιστος","o":14,"ar":"<f><o>ἐλάχιστος</o>، <g>-η, -ον</g></f> <s><b>أصغر، أقلّ</b>: بمعنى صيغة التفضيل العليا الحقيقية: <r v=\"1Cor.15.9\"></r>؛ وفي غيره، كما هو المعتاد في اليونانية المتأخرة، للتوكيد (صغير جدًّا): <r v=\"Matt.2.6\"></r> <i>(السبعينية)</i>، <r v=\"Matt.25.40\"></r>، <r v=\"Matt.25.45\"></r>، <r v=\"Luke.12.26\"></r>، <r v=\"Luke.16.10\"></r>، <r v=\"Luke.19.17\"></r>، <r v=\"1Cor.4.3\"></r>، <r v=\"1Cor.6.2\"></r>، <r v=\"Jas.3.4\"></r>؛ <g>ἐ. ἐν τ. βασιλείᾳ τ. οὐρανῶν</g>: <r v=\"Matt.5.19\"></r>. صيغة التفضيل: <g>ἐλαχιστότερος</g>: <b>أصغر من أصغر</b>: <r v=\"Eph.3.8\"></r>.†</s>","en":"<f><o>ἐλάχιστος</o>, <g>-η, -ον</g></f> <et> <e t=\"derivation\">(v.s. <g>ἐλάσσων</g>), </e> </et> <s><b>smallest, least</b>: as proper superlat., <r v=\"1Cor.15.9\"></r>; elsewhere, as usually in late Gk., intensive (B1., § 11, 3); <r v=\"Matt.2.6\"></r> <i>(LXX)</i> <r v=\"Matt.25.40\"></r>, <r v=\"Matt.25.45\"></r>, <r v=\"Luke.12.26\"></r> <r v=\"Luke.16.10\"></r> <r v=\"Luke.19.17\"></r>, <r v=\"1Cor.4.3\"></r> <r v=\"1Cor.6.2\"></r>, <r v=\"Jas.3.4\"></r>; <g>ἐ. ἐν τ. βασιλείᾳ τ. οὐρανῶν</g>, <r v=\"Matt.5.19\"></r> (v. Dalman, <i>Words</i>, 113). Compar., <g>ἐλαχιστότερος</g> (for corresp. superl., v. LS; v. also Bl., § 44, 3); <b>less than the least</b>: <r v=\"Eph.3.8\"></r>.†</s>"},"G1657":{"l":"ἐλευθερία","o":11,"ar":"<f><o>ἐλευθερία</o>، <g>-ας, ἡ </g></f> <s><b>حرية</b>: من جهة الحياة الدينية: <r v=\"1Cor.10.29\"></r>، <r v=\"2Cor.3.17\"></r>، <r v=\"Gal.2.4\"></r>، <r v=\"Gal.5.1\"></r>، <r v=\"1Pet.2.16\"></r>، <r v=\"2Pet.2.19\"></r>؛ <g>ὁ νόμος τῆς ἐ.</g>: <r v=\"Jas.1.25\"></r>، <r v=\"Jas.2.12\"></r>؛ <g>ἡ ἐ. τῆς δόξης</g>: <r v=\"Rom.8.21\"></r>؛ <g>ἐπ’ ἐ.</g>: <r v=\"Gal.5.13\"></r>.† </s>","en":"<f><o>ἐλευθερία</o>, <g>-ας, ἡ </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Lev.19.20\"></r> (<h n=\"H2668\">חֻפְשָׁה</h>), <r v=\"1Esd.4.49\"></r>, <r v=\"1Esd.4.53\"></r>, <r v=\"Sir.7.21\"></r>, <r v=\"Sir.33.25\"></r>, <r v=\"1Macc.14.27\"></r>, <r v=\"3Macc.3.28\"></r> * ;]</e> </et> <s><b>liberty</b>: with reference to the religious life, <r v=\"1Cor.10.29\"></r>, <r v=\"2Cor.3.17\"></r>, <r v=\"Gal.2.4\"></r> <r v=\"Gal.5.1\"></r>, <r v=\"1Pet.2.16\"></r>, <r v=\"2Pet.2.19\"></r>; <g>ὁ νόμος τῆς ἐ.</g>, <r v=\"Jas.1.25\"></r> <r v=\"Jas.2.12\"></r>; <g>ἡ ἐ. τῆς δόξης</g>, <r v=\"Rom.8.21\"></r>; <g>ἐπ’ ἐ.</g>, <r v=\"Gal.5.13\"></r> (on which formula, cf. Deiss., <i>LAE</i>, 327 ff.; Cremer, 251).† </s>"},"G1632":{"l":"ἐκχέω","o":27,"ar":"<f><o>ἐκ-χέω </o> وفي اليونانية المتأخرة أيضًا <g>ἐκχύνω</g> (في ترجمة ثيودوتيون: <r v=\"2Kgs.14.14\"></r> *)، و<g>ἐκχύννω</g> (انظره) </f> <s><b>يسكب</b>: <g>φιάλην</g>، <r v=\"Rev.16.1-Rev.16.4\"></r>، <r v=\"Rev.16.8\"></r>، <r v=\"Rev.16.10\"></r>، <r v=\"Rev.16.12\"></r>، <r v=\"Rev.16.17\"></r>؛ <g>κέρματα</g>، <r v=\"John.2.15\"></r>؛ <g>αἷμα</g>، <r v=\"Matt.23.35\"></r>، <r v=\"Luke.11.50\"></r>، <r v=\"Acts.22.20\"></r>، <r v=\"Rom.3.15\"></r> <i>(السبعينية)</i> <r v=\"Rev.16.6\"></r>. المبني للمجهول، <g>αἷμα</g>، <r v=\"Matt.26.28\"></r>، <r v=\"Mark.14.24\"></r>، <r v=\"Acts.22.20\"></r>؛ <g>οἶνος</g>، <r v=\"Matt.9.17\"></r>، <r v=\"Luke.5.37\"></r>؛ <g>σπλάγχνα</g>، <r v=\"Acts.1.18\"></r>. مجازيًا، <g>τ. πνεῦμα</g>، <r v=\"Acts.2.17\"></r>، <r v=\"Acts.2.18\"></r> <i>(السبعينية)</i>، <r v=\"Acts.2.33\"></r> <r v=\"Acts.10.45\"></r>، <r v=\"Titus.3.6\"></r>؛ <g>ἀγάπη</g>، <r v=\"Rom.5.5\"></r> (قارن <r v=\"Sir.36.8\"></r>، <g>ὀργήν</g>)؛ المبني للمجهول، عن الأشخاص (مثل اللاتينية <l>effundor</l>)، <b>يُسلم نفسه لـ</b> (الترجمة المنقحة: <b>اندفعوا بلا ضابط في</b>): <r v=\"Jude.1.11\"></r>.†</s>","en":"<f><o>ἐκ-χέω </o> also Hellenistic, <g>ἐκχύνω</g> (in <i>Th.</i>: <r v=\"2Kgs.14.14\"></r> *), and <g>ἐκχύννω</g> (q.v.) </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H8210\">שָׁפַךְ</h> ;] </e> </et> <s><b>to pour out</b>: <g>φιάλην</g>, <r v=\"Rev.16.1-Rev.16.4\"></r>, <r v=\"Rev.16.8\"></r>, <r v=\"Rev.16.10\"></r>, <r v=\"Rev.16.12\"></r>, <r v=\"Rev.16.17\"></r>; <g>κέρματα</g>, <r v=\"John.2.15\"></r>; <g>αἷμα</g>, <r v=\"Matt.23.35\"></r> (cf. MM, <i>Exp.</i>, xii), <r v=\"Luke.11.50\"></r>, <r v=\"Acts.22.20\"></r>, <r v=\"Rom.3.15\"></r> <i>(LXX)</i> <r v=\"Rev.16.6\"></r>. Pass., <g>αἷμα</g>, <r v=\"Matt.26.28\"></r>, <r v=\"Mark.14.24\"></r>, <r v=\"Acts.22.20\"></r>; <g>οἶνος</g>, <r v=\"Matt.9.17\"></r>, <r v=\"Luke.5.37\"></r>; <g>σπλάγχνα</g>, <r v=\"Acts.1.18\"></r>. Metaph., <g>τ. πνεῦμα</g>, <r v=\"Acts.2.17\"></r>, <r v=\"Acts.2.18\"></r> <i>(LXX)</i>, <r v=\"Acts.2.33\"></r> <r v=\"Acts.10.45\"></r>, <r v=\"Titus.3.6\"></r>; <g>ἀγάπη</g>, <r v=\"Rom.5.5\"></r> (cf. <r v=\"Sir.36.8\"></r>, <g>ὀργήν</g>); pass., of persons (like Lat. <l>effundor</l>), <b>to give oneself up to</b> (RV,<b> ran riotously in</b>): <r v=\"Jude.1.11\"></r>.†</s>"},"G1672":{"l":"Ἕλλην","o":25,"ar":"<f><o>Ἕλλην</o>، <g>-ηνος, ὁ </g></f> <s><b>يوناني</b>؛ عكس <g>βάρβαρος</g>، <r v=\"Rom.1.14\"></r>؛ وفي العهد الجديد غالبًا عن الأمميين اليونانيين، عكس <g>Ἰουδαῖοι</g>: <r v=\"John.7.35\"></r>، <r v=\"Acts.11.20\"></r> <r v=\"Acts.14.1\"></r> <r v=\"Acts.16.1\"></r>، <r v=\"Acts.16.3\"></r> <r v=\"Acts.18.4\"></r> <r v=\"Acts.19.10\"></r>، <r v=\"Acts.19.17\"></r> <r v=\"Acts.20.21\"></r> <r v=\"Acts.21.28\"></r>، <r v=\"Rom.1.16\"></r> <r v=\"Rom.2.9\"></r>، <r v=\"Rom.2.10\"></r> <r v=\"Rom.3.9\"></r> <r v=\"Rom.10.12\"></r>، <r v=\"1Cor.1.22\"></r>، <r v=\"1Cor.1.24\"></r> <r v=\"1Cor.10.32\"></r> <r v=\"1Cor.12.13\"></r>، <r v=\"Gal.2.3\"></r> <r v=\"Gal.3.28\"></r>، <r v=\"Col.3.11\"></r>؛ وعن الدخلاء (المتهوّدين)، <r v=\"John.12.20\"></r>، <r v=\"Acts.17.4\"></r>.†</s>","en":"<f><o>Ἕλλην</o>, <g>-ηνος, ὁ </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Joel.3.6\"></r>, <r v=\"Zech.9.13\"></r> (<h n=\"H3120\">יָוָן</h>), etc.; <r v=\"1Macc.1.10\"></r>, al. * ;]</e> </et> <s><b>a Greek</b>; opp. to <g>βάρβαρος</g>, <r v=\"Rom.1.14\"></r>; usually in ΝΤ of Greek Gentiles, opp. to <g>Ἰουδαῖοι</g>: <r v=\"John.7.35\"></r>, <r v=\"Acts.11.20\"></r> <r v=\"Acts.14.1\"></r> <r v=\"Acts.16.1\"></r>, <r v=\"Acts.16.3\"></r> <r v=\"Acts.18.4\"></r> <r v=\"Acts.19.10\"></r>, <r v=\"Acts.19.17\"></r> <r v=\"Acts.20.21\"></r> <r v=\"Acts.21.28\"></r>, <r v=\"Rom.1.16\"></r> <r v=\"Rom.2.9\"></r>, <r v=\"Rom.2.10\"></r> <r v=\"Rom.3.9\"></r> <r v=\"Rom.10.12\"></r>, <r v=\"1Cor.1.22\"></r>, <r v=\"1Cor.1.24\"></r> <r v=\"1Cor.10.32\"></r> <r v=\"1Cor.12.13\"></r>, <r v=\"Gal.2.3\"></r> <r v=\"Gal.3.28\"></r>, <r v=\"Col.3.11\"></r>; of proselytes, <r v=\"John.12.20\"></r>, <r v=\"Acts.17.4\"></r>.†</s>"},"G1653":{"l":"ἐλεέω","o":28,"ar":"<f><o>ἐλεέω</o></f> <s><b>أشفق </b>أو <b>رحم، صنع رحمة</b>: مطلقًا، <r v=\"Rom.9.16\"></r> <r v=\"Rom.12.8\"></r>؛ مع المنصوب، <r v=\"Matt.9.27\"></r> <r v=\"Matt.15.22\"></r> <r v=\"Matt.17.15\"></r> <r v=\"Matt.18.33\"></r> <r v=\"Matt.20.30\"></r>، <r v=\"Matt.20.31\"></r>، <r v=\"Mark.5.19\"></r> <r v=\"Mark.10.47\"></r>، <r v=\"Mark.10.48\"></r>، <r v=\"Luke.16.24\"></r> <r v=\"Luke.17.13\"></r> <r v=\"Luke.18.38\"></r>، <r v=\"Luke.18.39\"></r>، <r v=\"Rom.9.15\"></r>، <r v=\"Rom.9.18\"></r> <r v=\"Rom.11.32\"></r>، <r v=\"Phil.2.27\"></r>، <r v=\"Jude.1.22\"></r>. المبني للمجهول: <b>نال شفقة </b>أو <b>رُحِم</b> (أي نال رحمة): <r v=\"Matt.5.7\"></r>، <r v=\"Rom.11.30\"></r>، <r v=\"Rom.11.31\"></r>، <r v=\"1Cor.7.25\"></r>، <r v=\"2Cor.4.1\"></r>، <r v=\"1Tim.1.13\"></r>، <r v=\"1Tim.1.16\"></r>، <r v=\"1Pet.2.10\"></r>.†</s>","en":"<f><o>ἐλεέω</o></f> <et> <e t=\"derivation\">(in <r v=\"Rom.9.16\"></r>, <r v=\"Jude.1.22\"></r>, <g>-άω</g>, q.v.), <g>-ῶ</g> (&lt; <g>ἔλεος</g>), </e> <e t=\"septuagint\">[in LXX (Hex, Pss, Pr) chiefly for <h n=\"H2603\">חָנַן</h>, also freq. in Proph. for <h n=\"H7355\">רָחַם</h>, etc. ;]</e> </et> <s><b>to have pity </b>or <b>mercy on, to show mercy</b>: absol., <r v=\"Rom.9.16\"></r> <r v=\"Rom.12.8\"></r>; c. acc, <r v=\"Matt.9.27\"></r> <r v=\"Matt.15.22\"></r> <r v=\"Matt.17.15\"></r> <r v=\"Matt.18.33\"></r> <r v=\"Matt.20.30\"></r>, <r v=\"Matt.20.31\"></r>, <r v=\"Mark.5.19\"></r> <r v=\"Mark.10.47\"></r>, <r v=\"Mark.10.48\"></r>, <r v=\"Luke.16.24\"></r> <r v=\"Luke.17.13\"></r> <r v=\"Luke.18.38\"></r>, <r v=\"Luke.18.39\"></r>, <r v=\"Rom.9.15\"></r>, <r v=\"Rom.9.18\"></r> <r v=\"Rom.11.32\"></r>, <r v=\"Phil.2.27\"></r>, <r v=\"Jude.1.22\"></r>. Pass., <b>to have pity </b>or <b>mercy shown one</b> (EV, obtain mercy): <r v=\"Matt.5.7\"></r>, <r v=\"Rom.11.30\"></r>, <r v=\"Rom.11.31\"></r>, <r v=\"1Cor.7.25\"></r>, <r v=\"2Cor.4.1\"></r>, <r v=\"1Tim.1.13\"></r>, <r v=\"1Tim.1.16\"></r>, <r v=\"1Pet.2.10\"></r>.†</s> <sy><i>SYN.</i>: <g> οἰκτείρω </g> (v. Tr., <i>Syn</i>., § xlvii; Thayer, s.v. <g>ἐλεέω</g>; Cremer, 249). </sy>"},"G1659":{"l":"ἐλευθερόω","o":7,"ar":"<f><o>ἐλευθερόω</o>، <g>-ῶ </g></f> <s><b>حرّر، أعتق</b>: من الخطية، <r v=\"John.8.32\"></r>، <r v=\"John.8.36\"></r>؛ يليه <g>ἀπό</g>، <r v=\"Rom.6.18\"></r>، <r v=\"Rom.6.22\"></r> <r v=\"Rom.8.2\"></r>، <r v=\"Rom.8.21\"></r>؛ <g>τ. ἐλευθερία</g> (القابل للمنفعة)، <r v=\"Gal.5.1\"></r>.†</s>","en":"<f><o>ἐλευθερόω</o>, <g>-ῶ </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Prov.25.10\"></r>. <r v=\"2Macc.1.27\"></r> <r v=\"2Macc.2.22\"></r> * ;] </e> </et> <s><b>to make free</b>: from sin, <r v=\"John.8.32\"></r>, <r v=\"John.8.36\"></r>; seq. <g>ἀπό</g>, <r v=\"Rom.6.18\"></r>, <r v=\"Rom.6.22\"></r> <r v=\"Rom.8.2\"></r>, <r v=\"Rom.8.21\"></r>; <g>τ. ἐλευθερία</g> (dat. commodi), <r v=\"Gal.5.1\"></r> (on the \"punctiliar\" force of this verb, v. M, <i>Pr.</i> 149; cf. also Cremer, 251).†</s>"},"G1640":{"l":"ἐλάσσων","o":4,"ar":"<f><o>ἐλάσσων (-ττων</o> في <r v=\"Heb.7.7\"></r>، <r v=\"1Tim.5.9\"></r>)، <g>-ον</g></f> <s><b>أصغر، أقلّ</b>، في السن أو الرتبة أو النوع: <r v=\"John.2.19\"></r>، <r v=\"Rom.9.12\"></r> <i>(السبعينية)</i>، <r v=\"Heb.7.7\"></r>؛ المحايد <g>-ον</g> ظرفًا: <r v=\"1Tim.5.9\"></r>.†</s>","en":"<f><o>ἐλάσσων (-ττων</o>, <r v=\"Heb.7.7\"></r>, WH, <r v=\"1Tim.5.9\"></r>), <g>-ον</g></f> <et> <e t=\"derivation\">(formed, with superl. <g>ἐλάχιστος</g>, from the epic <g>ἐλαχύς</g>, <b>little</b>, and serving as compar. of <g>μικρός</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H4591\">מָעַט</h>, etc. ;] </e> </et> <s><b>less</b>, in age, rank or quality: <r v=\"John.2.19\"></r>, <r v=\"Rom.9.12\"></r> <i>(LXX)</i>, <r v=\"Heb.7.7\"></r>; neut., <g>-ον</g>, adverbially: <r v=\"1Tim.5.9\"></r>.†</s>"},"G1645":{"l":"ἐλαφρός","o":2,"ar":"<f><o>ἐλαφρός</o>، <g>-ά, -όν </g></f> <s><b>خفيف</b> الوزن، <b>سهل الحمل</b>: <r v=\"Matt.11.30\"></r>؛ <g>θλίψρις</g> (<b>خفة ضيقتنا</b>)، <r v=\"2Cor.4.17\"></r>.†</s>","en":"<f><o>ἐλαφρός</o>, <g>-ά, -όν </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7031\">קַל</h>, <h n=\"H7044\">קָלָל</h> ;] </e> </et> <s><b>light</b> in weight <b>easy to bear</b>: <r v=\"Matt.11.30\"></r>; <g>θλίψρις</g> (EV, <b>our light affliction</b>), <r v=\"2Cor.4.17\"></r>.†</s>"},"G1626":{"l":"ἔκτρωμα","o":1,"ar":"<f><o>ἔκ-τρωμα</o>، <g>-τος, τό</g></f> <s><b>سِقط، مولود قبل أوانه</b>: <r v=\"1Cor.15.8\"></r>.†</s>","en":"<f><o>ἔκ-τρωμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>ἐκτιτρώσκω</g>, <b>to miscarry</b>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Job.3.16\"></r>, <r v=\"Eccl.6.3\"></r> (<h n=\"H5307\">נָפַל</h>; also in Aq., <r v=\"Ps.58.9\"></r>, <r v=\"Num.12.12\"></r> (<h n=\"H5307\">מוּת</h>) * ;] </e> </et> <s><b>an abortion, an untimely birth</b> (v. Field, <i>Notes</i>, 179): <r v=\"1Cor.15.8\"></r>.†</s>"},"G1627":{"l":"ἐκφέρω","o":8,"ar":"<f><o>ἐκ-φέρω </o></f> <s n=\"1.\"><b>يُخرج، يحمل إلى الخارج</b>: مع المنصوب للشيء، <r v=\"Luke.15.22\"></r>، <r v=\"1Tim.6.7\"></r>؛ مع المنصوب للشخص، <r v=\"Mark.8.23\"></r>، <r v=\"Acts.5.15\"></r>؛ عن حمل الموتى للدفن (قارن <g>κομίζω</g>)، <r v=\"Acts.5.6\"></r>، <r v=\"Acts.5.9\"></r>، <r v=\"Acts.5.10\"></r>. </s> <s n=\"2.\"><b>يُخرج، يُنتج</b>؛ </s> <s n=\"(a)\">في اليونانية الكلاسيكية: عن النساء (يلدن)؛ </s> <s n=\"(b)\">عن الأرض: <r v=\"Heb.6.8\"></r>.†</s>","en":"<f><o>ἐκ-φέρω </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3318\">יָצָא</h> hi. ;] </e> </et> <s n=\"1.\"><b>to carry out, bring out</b>: cc. acc rei, <r v=\"Luke.15.22\"></r>, <r v=\"1Tim.6.7\"></r>; c. acc pers., <r v=\"Mark.8.23\"></r>, <r v=\"Acts.5.15\"></r>; of the dead for burial (cf. <g>κομίζω</g>), <r v=\"Acts.5.6\"></r>, <r v=\"Acts.5.9\"></r>, <r v=\"Acts.5.10\"></r>. </s> <s n=\"2.\"><b>to bring forth</b>; </s> <s n=\"(a)\">of women (Hipp., Arist., al.); </s> <s n=\"(b)\">of the ground (Hdt.): <r v=\"Heb.6.8\"></r>.†</s>"},"G1696":{"l":"ἐμμένω","o":4,"ar":"<f><o>ἐμμένω </o></f> <s n=\"1.\"><b>يمكث في، يبقى في</b>: <r v=\"Acts.28.30\"></r>. </s> <s n=\"2.\"><b>يثبت في، يبقى أمينًا لـ</b>: يليه <g>ἐν</g>؛ <g>τ. πίστει</g>، <r v=\"Acts.14.22\"></r>؛ <g>τ. διαθήκῃ</g>، <r v=\"Heb.8.9\"></r> <i>(السبعينية)</i>؛ مع القابل، <g>τ. γεγραμμένοις</g> (اسم الفاعل في حالة القابل كما في الصيغ القانونية): <r v=\"Gal.3.10\"></r> <i>(السبعينية)</i>.†</s>","en":"<f><o>ἐμμένω </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6965\">קוּם</h> ;] </e> </et> <s n=\"1.\"><b>to abide in</b>: <r v=\"Acts.28.30\"></r>. </s> <s n=\"2.\"><b>to abide by, be true to</b>: seq. <g>ἐν</g>; <g>τ. πίστει</g>, <r v=\"Acts.14.22\"></r>; <g>τ. διαθήκῃ</g>, <r v=\"Heb.8.9\"></r> <i>(LXX)</i>; c. dat., <g>τ. γεγραμμένοις</g> (dat. ptcp. as in legal formula; cf. Deiss., BS, 248; MM, <i>Exp.</i>, xii): <r v=\"Gal.3.10\"></r> <i>(LXX)</i>.†</s>"},"G1628":{"l":"ἐκφεύγω","o":8,"ar":"<f><o>ἐκ-φεύγω </o></f> <s><b>هرب، نجا، أفلت</b>: مطلقًا، <r v=\"Acts.16.27\"></r>، <r v=\"1Thess.5.3\"></r>، <r v=\"Heb.2.3\"></r>؛ يليه <g>ἐκ</g>، <r v=\"Acts.19.16\"></r>؛ مع منصوب الشخص، <r v=\"Heb.12.25\"></r>؛ مع الشيء، <r v=\"Luke.21.36\"></r>، <r v=\"Rom.2.3\"></r>؛ <g>τ. χεῖρας αὐτοῦ</g> (من يديه)، <r v=\"2Cor.11.33\"></r>.†</s>","en":"<f><o>ἐκ-φεύγω </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H5127\">נוּס</h>, etc. ;] </e> </et> <s><b>to flee away, escape</b>: absol., <r v=\"Acts.16.27\"></r>, <r v=\"1Thess.5.3\"></r>, <r v=\"Heb.2.3\"></r>; seq. <g>ἐκ</g>, <r v=\"Acts.19.16\"></r>; c. acc pers., <r v=\"Heb.12.25\"></r>; c. rei, <r v=\"Luke.21.36\"></r>, <r v=\"Rom.2.3\"></r>; <g>τ. χεῖρας αὐτοῦ</g>, <r v=\"2Cor.11.33\"></r>.†</s>"},"G1642":{"l":"ἐλαττόω","o":3,"ar":"<f><o>ἐλαττόω</o>، <g>-ῶ</g></f> <s><b>أنقص، جعله أقل، وضعه</b>: <r v=\"Heb.2.7\"></r> <i>(السبعينية)</i>؛ المبني للمجهول، <r v=\"John.3.30\"></r>، <r v=\"Heb.2.9\"></r>.†</s>","en":"<f><o>ἐλαττόω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>ἐλάιττων</g>), </e> <e t=\"septuagint\">[in LXX (where also <g>-σσῶ</g>) chiefly for <h n=\"H2637\">חָסֵר</h>, and very freq. in Si;] </e> </et> <s><b>to make less</b>: <r v=\"Heb.2.7\"></r> <i>(LXX)</i>; pass., <r v=\"John.3.30\"></r>, <r v=\"Heb.2.9\"></r>.†</s>"},"G1668":{"l":"ἕλκος","o":3,"ar":"<f><o>ἕλκος</o>، <g>-εος (-ους), τό</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>جرح</b>. </s> <s n=\"2.\"><b>قرحة، دُمَّل</b>: <r v=\"Luke.16.21\"></r>، <r v=\"Rev.16.2\"></r>، <r v=\"Rev.16.11\"></r>.†</s>","en":"<f><o>ἕλκος</o>, <g>-εος (-ους), τό</g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Exod.9.9-Exod.9.11\"></r>, <r v=\"Lev.13.18-Lev.13.27\"></r>, <r v=\"2Kgs.20.7\"></r>, <r v=\"Job.2.7\"></r> (<h n=\"H7822\">שְׁחִין</h>) ;]</e> </et> <s n=\"1.\"><b>a wound</b> (Hom.). </s> <s n=\"2.\"><b>a sore, an ulcer</b> (Thuc., al.): <r v=\"Luke.16.21\"></r>, <r v=\"Rev.16.2\"></r>, <r v=\"Rev.16.11\"></r>.†</s>"},"G1667":{"l":"ἑλίσσω","o":2,"ar":"<f><o>ἑλίσσω </o></f> <s><b>لفّ، طوى</b>: <r v=\"Heb.1.12\"></r> <i>(السبعينية)</i>، <r v=\"Rev.6.14\"></r>.†</s>","en":"<f><o>ἑλίσσω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Isa.34.4\"></r> (<h n=\"H1556\">גָּלַל</h> ni.), <r v=\"Ps.102.26\"></r> (<h n=\"H2498\">חָלַף</h> hi.), etc. ;]</e> </et> <s><b>to roll, roll up</b>: <r v=\"Heb.1.12\"></r> <i>(LXX)</i>, <r v=\"Rev.6.14\"></r>.†</s>"},"G1655":{"l":"ἐλεήμων","o":2,"ar":"<f><o>ἐλεήμων</o>، <g>-ον </g></f> <s><b>رحيم:</b> <r v=\"Matt.5.7\"></r>، <r v=\"Heb.2.17\"></r>.†</s>","en":"<f><o>ἐλεήμων</o>, <g>-ον </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2587\">חַנּוּן</h> ;] </e> </et> <s><b>merciful:</b> <r v=\"Matt.5.7\"></r>, <r v=\"Heb.2.17\"></r>.†</s>"},"G1623":{"l":"ἐκτός","o":8,"ar":"<f><o>ἐκτός</o>، </f> ظرف <s n=\"1.\">بوصفه ظرفًا، <b>خارج، وراء</b>: <g>τὸ ἐ.</g>، مع المضاف إليه للملكية، <b>الخارج</b>، <r v=\"Matt.23.26\"></r>؛ وفي اليونانية المتأخرة، للتوكيد الزائد، <g>ἐκτός εἰ μή</g>، <r v=\"1Cor.14.5\"></r> <r v=\"1Cor.15.2\"></r>، <r v=\"1Tim.5.19\"></r>. </s> <s n=\"2.\">بقوة حرف الجر، مع المضاف إليه؛ </s> <s n=\"(a)\"><b>خارج عن</b>: <r v=\"1Cor.6.18\"></r>، <r v=\"2Cor.12.2\"></r>؛ </s> <s n=\"(b)\"><b>فيما عدا، سوى، إلا</b>: <r v=\"Acts.26.22\"></r>، <r v=\"1Cor.15.27\"></r>.†</s>","en":"<f><o>ἐκτός</o>, </f> adv. <et> <e t=\"septuagint\">[in LXX <r v=\"Judg.8.26\"></r> <r v=\"Judg.20.15\"></r>, <r v=\"1Kgs.10.13\"></r>, al. (<h n=\"H905,H4480\">לִבַד מִן ,מִלְּבַד</h>, <r v=\"Judg.5.28\"></r> (<h n=\"H905\">בְּﬠַד</h>),<r v=\"Song.4.3\"></r> (<h n=\"H905\">מִבַּﬠַד לִִ</h>), al, ;] </e> </et> <s n=\"1.\">as adv., <b>outside, beyond</b>: <g>τὸ ἐ.</g>, c. poss. gen., <b>the outside</b>, <r v=\"Matt.23.26\"></r>; in late Gk. (v. Deiss., BS, 118), pleonastic, <g>ἐκτός εἰ μή</g>, <r v=\"1Cor.14.5\"></r> <r v=\"1Cor.15.2\"></r>, <r v=\"1Tim.5.19\"></r>. </s> <s n=\"2.\">With force of prep., c. gen.; </s> <s n=\"(a)\"><b>outside of</b>: <r v=\"1Cor.6.18\"></r>, <r v=\"2Cor.12.2\"></r>; </s> <s n=\"(b)\"><b>beyond, besides, except</b>: <r v=\"Acts.26.22\"></r>, <r v=\"1Cor.15.27\"></r>.†</s>"},"G1618":{"l":"ἐκτενής","o":2,"ar":"<f>** <o>ἐκτενής</o>، <g>-ές</g></f> <s><b>ممدود، مشدود</b>. مجازيًا، <b>حارّ، شديد (غيور)</b>: <r v=\"1Pet.4.8\"></r> .†</s>","en":"<f>** <o>ἐκτενής</o>, <g>-ές</g></f> <et> <e t=\"derivation\">(&lt; <g>ἐκτείνω</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"3Macc.3.10\"></r> <r v=\"3Macc.5.29\"></r> * ;]</e> </et> <s><b>stretched, strained</b>. Metaph., <b>earnest, zealous</b>: <r v=\"1Pet.4.8\"></r> .†</s>"},"G1692":{"l":"ἐμέω","o":1,"ar":"<f><o>ἐμέω</o>، <g>-ῶ </g></f> <s><b>تقيّأ</b>: مجازيًا، <r v=\"Rev.3.16\"></r>.†</s>","en":"<f><o>ἐμέω</o>, <g>-ῶ </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Isa.19.14\"></r> (<h n=\"H6892\">קֵא</h>)* ;]</e> </et> <s><b>to vomit</b>: fig., <r v=\"Rev.3.16\"></r>.†</s>"},"G1637":{"l":"ἔλαιον","o":11,"ar":"<f><o>ἔλαιον</o>، <g>-ου, τό </g></f> <s><b>زيت الزيتون</b>: <r v=\"Luke.16.6\"></r>، <r v=\"Rev.6.6\"></r>، <r v=\"Rev.18.13\"></r>؛ للمصابيح، <r v=\"Matt.25.3\"></r>، <r v=\"Matt.25.4\"></r>، <r v=\"Matt.25.8\"></r>؛ للشفاء، <r v=\"Mark.6.13\"></r>، <r v=\"Luke.10.34\"></r>، <r v=\"John.5.14\"></r>؛ للدهن في الولائم، <r v=\"Luke.7.46\"></r>، <r v=\"Heb.1.9\"></r> <i>(السبعينية)</i>.†</s>","en":"<f><o>ἔλαιον</o>, <g>-ου, τό </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H8081\">שֶׁמֶן</h> ;]</e> </et> <s><b>olive-oil</b>: <r v=\"Luke.16.6\"></r>, <r v=\"Rev.6.6\"></r> <r v=\"Rev.18.13\"></r>; for lamps, <r v=\"Matt.25.3\"></r>, <r v=\"Matt.25.4\"></r>, <r v=\"Matt.25.8\"></r>; for healing, <r v=\"Mark.6.13\"></r>, <r v=\"Luke.10.34\"></r>, <r v=\"John.5.14\"></r>; for anointing at feasts, <r v=\"Luke.7.46\"></r>, <r v=\"Heb.1.9\"></r> <i>(LXX)</i>.†</s> <sy><i>SYN.</i>: <g>μύρον</g>, <b>ointment</b>, v. Tr., <i>Syn.</i>, 135 </sy>"},"G1673":{"l":"Ἑλληνικκός","o":1,"ar":"<f><o>Ἑλληνικκός</o>، <g>-ή, -όν </g></f> <s><b>يونانيّ</b>: <g>τ. Ἑλληνικῇ</g> (أي <g>γλωσσῇ</g>)، <r v=\"Rev.9.11\"></r>.†</s>","en":"<f><o>Ἑλληνικκός</o>, <g>-ή, -όν </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Jer.46.6\"></r> <r v=\"Jer.50.16\"></r> (<h n=\"H3238\">יָנָה</h>: aliter in <i>Heb.</i>), <r v=\"2Macc.4.10\"></r>, <r v=\"2Macc.4.15\"></r> <r v=\"2Macc.6.9\"></r> <r v=\"2Macc.11.24\"></r> <r v=\"2Macc.13.2\"></r>, <r v=\"4Macc.8.8\"></r> * ;]</e> </et> <s><b>Greek</b>: <g>τ. Ἑλληνικῇ</g> (sc. <g>γλωσσῇ</g>), <r v=\"Rev.9.11\"></r>.†</s>"},"G1630":{"l":"ἔκφοβος","o":2,"ar":"<f><o>ἔκφοβος</o>، <g>-ον </g></f> <s><b>مرتعب، خائف جدًا</b>: <r v=\"Mark.9.16\"></r>، <r v=\"Heb.12.21\"></r>.†</s>","en":"<f><o>ἔκφοβος</o>, <g>-ον </g></f> <et> <e t=\"septuagint\">[in LXX: <g>ἔ. εἶναι</g> for <h n=\"H3025\">יָגֹר</h>, <r v=\"Deut.9.19\"></r>; also <r v=\"1Macc.13.2\"></r> * ;]</e> </et> <s><b>affrighted, terrified</b>: <r v=\"Mark.9.16\"></r>, <r v=\"Heb.12.21\"></r>.†</s>"},"G1661":{"l":"ἐλεφάντινος","o":1,"ar":"<f><o>ἐλεφάντινος</o>، <g>-η, -ον</g></f> <s><b>من العاج</b>: <r v=\"Rev.18.12\"></r>.†</s>","en":"<f><o>ἐλεφάντινος</o>, <g>-η, -ον</g></f> <et> <e t=\"derivation\">(&lt; <g>ἐλέφας</g>, <b>ivory</b>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H8127\">שֵׁן</h> ;] </e> </et> <s><b>of ivory</b>: <r v=\"Rev.18.12\"></r>.†</s>"},"G1610":{"l":"ἐκριζόω","o":4,"ar":"<f>† <o>ἐκ-ριζόω</o>، <g>-ῶ </g></f> <s><b>اقتلع، استأصل من الجذور</b>: مع منصوب الشيء، <r v=\"Matt.13.29\"></r>، <r v=\"Matt.15.13\"></r>، <r v=\"Luke.17.6\"></r>، <r v=\"Jude.1.12\"></r>.†</s>","en":"<f>† <o>ἐκ-ριζόω</o>, <g>-ῶ </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Judg.5.14\"></r> (<h n=\"H8328\">שֶׁרֶשׁ</h>), <r v=\"Jer.1.10\"></r> (<h n=\"H5428\">נָתַשׁ</h>), <r v=\"Zeph.2.4\"></r> (<h n=\"H1644\">גָּרַשׁ</h> A, <h n=\"H6131\">עָקַר</h> BS), <r v=\"Dan.7.8\"></r> (<h n=\"H6131\">עָקַר</h>), <r v=\"Dan.4.11\"></r>, <r v=\"Dan.4.23\"></r>, <r v=\"Wis.4.4\"></r>, <r v=\"Sir.3.9\"></r> <r v=\"Sir.49.7\"></r>, <r v=\"1Macc.5.51\"></r>, <r v=\"2Macc.12.7\"></r> * ;]</e> </et> <s><b>to root out, pluck up by the roots</b>: c. acc rei, <r v=\"Matt.13.29\"></r> <r v=\"Matt.15.13\"></r> <r v=\"Luke.17.6\"></r>, <r v=\"Jude.1.12\"></r>.†</s>"},"G1608":{"l":"ἐκπορνεύω","o":1,"ar":"<f>† <o>ἐκ-πορνεύω </o></f> <s>صيغة مشدَّدة من <g>πoρνεύω</g>، تدل على الإفراط؛ الصيغة الوسطى، <b>أسلم نفسه للزنى</b>: <r v=\"Jude.1.7\"></r>.†</s>","en":"<f>† <o>ἐκ-πορνεύω </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2181\">זָנָה</h>, freq. of spiritual unfaithfulness ;] </e> </et> <s>strengthened form of <g>πoρνεύω</g>, implying excessive indulgence; mid, <b>to give oneself up to fornication</b>: <r v=\"Jude.1.7\"></r>.†</s>"},"G1619":{"l":"ἐκτενῶς","o":3,"ar":"<f><o>ἐκτενῶς </o></f> ظرف، <s><b>بحرارة، بلجاجة، بإلحاح</b>: <r v=\"Acts.12.5\"></r>، <r v=\"1Pet.1.22\"></r>؛ صيغة التفضيل، <r v=\"Luke.22.44\"></r>.†</s>","en":"<f><o>ἐκτενῶς </o></f> adv., <et> <e t=\"septuagint\">[in LXX: <r v=\"Jon.3.8\"></r> (<h n=\"H2394\">חׇזְקָה</h>), <r v=\"Joel.1.14\"></r>, <r v=\"Jdt.4.12\"></r>, <r v=\"3Macc.5.9\"></r> * ;]</e> </et> <s><b>fervently, earnestly</b>: <r v=\"Acts.12.5\"></r>, <r v=\"1Pet.1.22\"></r>; compar., <r v=\"Luke.22.44\"></r> (WH br., R, mg., omits).†</s>"},"G1649":{"l":"ἔλεγξις","o":1,"ar":"<f>† <o>ἔλεγξις</o>، <g>-εως, ἡ</g></f> <s><b>توبيخ</b>: <r v=\"2Pet.2.16\"></r>.†</s>","en":"<f>† <o>ἔλεγξις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>ἐλέγχω</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Job.21.4\"></r> <r v=\"Job.23.2\"></r> (<h n=\"H7879\">שִׂיחַ</h>) * ;] </e> </et> <s><b>rebuke</b>: <r v=\"2Pet.2.16\"></r>.†</s>"},"G1670":{"l":"ἕλκω","o":8,"ar":"<f><o>ἕλκω </o></f> <s><b>يجذب، يسحب، يستلّ</b>: مع المنصوب للشيء، <r v=\"John.18.10\"></r> <r v=\"John.21.6\"></r>؛ مع المنصوب للشخص، يليه <g>ἔξω</g>، <r v=\"Acts.21.30\"></r>؛ <g>εἰς</g>، <r v=\"Acts.16.19\"></r>، <r v=\"Jas.2.6\"></r>. مجازيًا: <b>يجتذب، يقود، يدفع</b>: <r v=\"John.6.44\"></r> <r v=\"John.12.32\"></r>.†</s>","en":"<f><o>ἕλκω </o></f> <et> <e t=\"derivation\">(Hellenistic form <g>ἑλκύω</g> in Jo, ll. c., <r v=\"Acts.16.19\"></r>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H4900\">מָשַׁךְ</h>, etc. ;] </e> </et> <s><b>to draw</b>: c. acc rei, <r v=\"John.18.10\"></r> <r v=\"John.21.6\"></r>; c. acc pers., seq. <g>ἔξω</g>, <r v=\"Acts.21.30\"></r>; <g>εἰς</g>, <r v=\"Acts.16.19\"></r>, <r v=\"Jas.2.6\"></r>. Metaph., <b>to draw, lead, impel</b>: <r v=\"John.6.44\"></r> <r v=\"John.12.32\"></r>. (For discussion of <g>ἕ.</g> in <i>Oxyrh. Log.</i>, v. Deiss., <i>LAE</i>, 437 ff.)†</s>"},"G1643":{"l":"ἐλαύνω","o":5,"ar":"<f><o>ἐλαύνω </o></f> <s><b>يسوق، يدفع</b>: عن الريح، <r v=\"Jas.3.4\"></r>، <r v=\"2Pet.2.17\"></r>؛ عن البحّارة يجذّفون أو يسيّرون القارب، <r v=\"Mark.6.48\"></r>، <r v=\"John.6.19\"></r>؛ عن الشياطين، <r v=\"Luke.8.29\"></r> (قارن <g>ἀπ-</g>، <g>συν-ελαύνω</g>).†</s>","en":"<f><o>ἐλαύνω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Isa.41.7\"></r> (<h n=\"H1986\">הָלַם</h>) <r v=\"Isa.33.21\"></r> (<h n=\"H7885\">שַׁיִט</h>), etc. ;] </e> </et> <s><b>to drive</b>: of the wind, <r v=\"Jas.3.4\"></r>, <r v=\"2Pet.2.17\"></r>; of sailors rowing or sailing a boat, <r v=\"Mark.6.48\"></r>, <r v=\"John.6.19\"></r>; of demons, <r v=\"Luke.8.29\"></r> (cf. <g>ἀπ-</g>, <g>συν-ελαύνω</g>).†</s>"},"G1694":{"l":"Ἐμμανουήλ","o":1,"ar":"<f>† <o>Ἐμμανουήλ</o>، <g>ὁ</g> (العبرية <h n=\"H6005\">עִמָּנוּ אֵל</h>، <r v=\"Isa.7.14\"></r>)، </f> <s><b>عمانوئيل</b>: <r v=\"Matt.1.23\"></r> <i>(السبعينية)</i>.†</s>","en":"<f>† <o>Ἐμμανουήλ</o>, <g>ὁ</g> (Heb. <h n=\"H6005\">עִמָּנוּ אֵל</h>, <r v=\"Isa.7.14\"></r>), </f> <s><b>Immanuel</b>: <r v=\"Matt.1.23\"></r> <i>(LXX)</i>.†</s>"},"G1671":{"l":"Ἑλλάς","o":1,"ar":"<f><o>Ἑλλάς</o>، <g>-άδος, ἡ </g></f> <s>تختلف حدوده الجغرافية بحسب الاستعمال؛ وفي العهد الجديد = <g>Αχαία</g> (قارن <r v=\"Acts.18.12\"></r>)، </s> <s><b>اليونان (هلاس)</b>: <r v=\"Acts.20.2\"></r>.†</s>","en":"<f><o>Ἑλλάς</o>, <g>-άδος, ἡ </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Isa.66.19\"></r>, <r v=\"Ezek.27.13\"></r> (<h n=\"H3120\">יָוָן</h>), <r v=\"1Macc.1.1\"></r> <r v=\"1Macc.8.9\"></r> * ;] </e> </et> <s>with varying usage as to geographical limits; in NT = '<g>Αχαία</g> (cf. <r v=\"Acts.18.12\"></r>), </s> <s><b>Greece</b>: <r v=\"Acts.20.2\"></r>.†</s>"},"G1666":{"l":"Ἐλισαῖος","o":1,"ar":"<f><o>Ἐλισαῖος</o>، <g>-ου, ὁ</g> (العبرية <h n=\"H477\">אֱלִישָׁע</h>)، </f> <s><b>أليشع</b>، النبي: <r v=\"Luke.4.27\"></r>.†</s>","en":"<f><o>Ἐλισαῖος</o> (Rec. <g>Ἐλισσαῖος</g>; T, <g>Ἑλισ-</g>), <g>-ου, ὁ</g> (Heb. <h n=\"H477\">אֱלִישָׁע</h>), </f> <s><b>Elisha</b>, the prophet: <r v=\"Luke.4.27\"></r>.†</s>"},"G1697":{"l":"Ἑμμώρ","o":null,"ar":"<f><o>Ἑμμώρ</o> لا يُصرَّف (العبرية <h n=\"H2543\">חֲמוֹר</h>)، </f> <s><b>حمور</b> (<r v=\"Gen.33.19\"></r>): <r v=\"Acts.7.16\"></r>.†</s>","en":"<f><o>Ἑμμώρ</o> (T, <g>Ἐμμώρ</g>, Rec. <g>-όρ</g> indecl. (Heb. <h n=\"H2543\">חֲמוֹר</h>), </f> <s><b>Emmor</b> (<r v=\"Gen.33.19\"></r>): <r v=\"Acts.7.16\"></r>.†</s>"},"G1678":{"l":"Ἐλμαδάμ","o":null,"ar":"<f><o>Ἐλμαδάμ</o>، <g>ό</g>، لا يُصرَّف، </f> <s><b>ألمودام</b>، أحد أسلاف يسوع: <r v=\"Luke.3.28\"></r>. </s>","en":"<f><o>Ἐλμαδάμ</o> (L, <g>Ἑλ-</g>; Rec. <g>-μωδάμ</g>), <g>ό</g>, indecl., </f> <s><b>Elmadam</b>, an ancestor of Jesus: <r v=\"Luke.3.28\"></r>. </s>"},"G1615":{"l":"ἐκτελέω","o":2,"ar":"<f><o>ἐκ-τελέω</o>، <g>-ῶ </g></f> <s><b>أنهى، أكمل، أتمّ</b>: <r v=\"Luke.14.29\"></r>، <r v=\"Luke.14.30\"></r>.†</s>","en":"<f><o>ἐκ-τελέω</o>, <g>-ῶ </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Deut.32.45\"></r> (<h n=\"H3615\">כָּלָה</h>), <r v=\"2Chr.4.5\"></r>, <r v=\"Dan.3.40\"></r>, <r v=\"2Macc.15.9\"></r> * ;]</e> </et> <s><b>to bring to an end, finish, complete</b>: <r v=\"Luke.14.29\"></r>, <r v=\"Luke.14.30\"></r>.†</s>"},"G1674":{"l":"Ἑλληνίς","o":2,"ar":"<f><o>Ἑλληνίς</o></f> <s><b>امرأة يونانية</b> (أي <b>أممية</b>): <r v=\"Mark.7.26\"></r>، <r v=\"Acts.17.12\"></r>.†</s>","en":"<f><o>Ἑλληνίς</o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"2Macc.6.8\"></r> A * ;] </e> </et> <s><b>a Greek</b> (i.e. <b>Gentile</b>) <b>woman</b>: <r v=\"Mark.7.26\"></r>, <r v=\"Acts.17.12\"></r>.†</s>"},"G1681":{"l":"Ἐλύμας","o":1,"ar":"<f><o>Ἐλύμας</o>، <g>-α, ὁ</g></f> <s><b>عليم</b>: <r v=\"Acts.13.8\"></r>.†</s>","en":"<f><o>Ἐλύμας</o>, <g>-α, ὁ</g></f> <et> <e t=\"derivation\">(&lt; Aram. or Arab., cf. <i>DB</i>, i, 246 b) </e> </et> <s><b>Elymas</b>: <r v=\"Acts.13.8\"></r>.†</s>"},"G1693":{"l":"ἐμμαίνομαι","o":1,"ar":"<f>*† <o>ἐμ-μαίνομαι </o> فعل لازم الصيغة الوسطى، </f> <s><b>يحنق على</b>: مع القابل، <r v=\"Acts.26.11\"></r>.†</s>","en":"<f>*† <o>ἐμ-μαίνομαι </o> depon., </f> <s><b>to rage against</b>: c. dat., <r v=\"Acts.26.11\"></r>.†</s>"},"G1660":{"l":"ἔλευσις","o":1,"ar":"<f>*† <o>ἔλευσις</o>، <g>-εως, ἡ</g></f> <s><b>مجيء</b>: <r v=\"Acts.7.52\"></r>.†</s>","en":"<f>*† <o>ἔλευσις</o>, <g>-εως, ἡ</g></f> <s><b>a coming</b>: <r v=\"Acts.7.52\"></r>.†</s>"},"G1638":{"l":"ἐλαιών","o":3,"ar":"<f>† <o>ἐλαιών</o>، <g>-ῶνος, ὁ</g></f> <s><b>بستان زيتون، كرم زيتون</b>: <r v=\"Luke.19.29\"></r> <r v=\"Luke.21.37\"></r>، <r v=\"Acts.1.12\"></r>.†</s>","en":"<f>† <o>ἐλαιών</o>, <g>-ῶνος, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>ἐλαία</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H2132\">זַיִת</h> ;] </e> </et> <s><b>olive-grove, olive-garden</b> (so in FlJ and in <g>π.</g>; Deiss., <i>BS</i>, 209 ff.; MM, <i>Exp.</i>, iii; M, <i>Pr.</i>, 49, 69, 235): <r v=\"Luke.19.29\"></r> <r v=\"Luke.21.37\"></r> (WH, <g>-ῶν</g>; v. their <i>App.</i>, 158; Field, <i>Notes</i>, 73; Bl., § 10, 5; 33, 1; Thayer, s.v.), <r v=\"Acts.1.12\"></r> (where Bl, ll. c., proposes the conjectural emendation <g>ἐλαιῶν</g> for <g>-ῶνος</g>).†</s>"},"G1669":{"l":"ἑλκόω","o":1,"ar":"<f>* <o>ἑλκόω</o>، <g>-ῶ </g></f> <s n=\"1.\"><b>جرح</b>. </s> <s n=\"2.\"><b>قرّح</b>؛ وفي المبني للمجهول: <b>أصيب بالقروح</b>: اسم الفاعل التام <g>εἱλκωμίνος</g>: <b>مضروب بالقروح</b>، <r v=\"Luke.16.20\"></r>.†</s>","en":"<f>* <o>ἑλκόω</o>, <g>-ῶ </g></f> <s n=\"1.\"><b>to wound</b>. </s> <s n=\"2.\"><b>to ulcerate</b>; pass., <b>to suffer from sores</b>: pf. ptcp., <g>εἱλκωμίνος</g> (Rec. <g>ἡλκ-</g>), EV, <b>full of sores</b>, <r v=\"Luke.16.20\"></r>.†</s>"},"G1602":{"l":"ἐκπλέω","o":3,"ar":"<f>* <o>ἐκ-πλέω</o>، <g>-ῶ </g></f> <s><b>سافر بحرًا، أقلع</b>: <r v=\"Acts.20.6\"></r>؛ يليه <g>εἰς</g>، <r v=\"Acts.15.39\"></r> <r v=\"Acts.18.18\"></r>.†</s>","en":"<f>* <o>ἐκ-πλέω</o>, <g>-ῶ </g></f> <s><b>to sail away</b>: <r v=\"Acts.20.6\"></r>; seq. <g>εἰς</g>, <r v=\"Acts.15.39\"></r> <r v=\"Acts.18.18\"></r>.†</s>"},"G1639":{"l":"Ἐλαμείτης","o":1,"ar":"<f><o>Ἐλαμείτης</o>، <g>-ου, ὁ</g> </f> <s><b>عيلامي</b>: <r v=\"Acts.2.9\"></r>.†</s>","en":"<f><o>Ἐλαμείτης</o> (Rec. <g>-αμίτης</g>), <g>-ου, ὁ</g> </f> <et> <e t=\"derivation\">(Heb. <h n=\"H361\">אֵילָם</h>) </e> <e t=\"septuagint\">[in LXX (cl.) <g>Ἐλυμαίος, Ἔλαμος</g>: <r v=\"Jdt.1.6\"></r>; <g>Ἀιλαμείτης</g> (vv.ll. <g>Ἐλ-, -αμίτης</g>; Bl., § 3, 7): <r v=\"Isa.11.11\"></r> <r v=\"Isa.21.2\"></r> <r v=\"Isa.22.6\"></r>) ;] </e> </et> <s><b>an Elamite</b>: <r v=\"Acts.2.9\"></r>.†</s>"},"G1613":{"l":"ἐκταράσσω","o":1,"ar":"<f><o>ἐκ-ταράσσω </o></f> <s><b>أزعج جدًا، بلبل</b>: <r v=\"Acts.16.20\"></r>.†</s>","en":"<f><o>ἐκ-ταράσσω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Ps.18.4\"></r> (<h n=\"H6256\">בּﬠת</h> pi.), <r v=\"Ps.88.16\"></r> (<h n=\"H6684\">צמת</h>), <r v=\"Wis.17.3\"></r>, <r v=\"Wis.17.4\"></r> <r v=\"Wis.18.17\"></r> * ;] </e> </et> <s><b>to throw into great trouble, agitate</b>: <r v=\"Acts.16.20\"></r>.†</s>"},"G1654":{"l":"ἐλεημοσύνη","o":13,"ar":"<f>† <o>ἐλεημοσύνη</o>، <g>-ης, ἡ</g></f> <s n=\"1.\"><b>رحمة، شفقة</b>. </s> <s n=\"2.\"><b>صَدَقة، إحسان</b>: <r v=\"Matt.6.4\"></r>؛ <g>ποιεῖν ἐ.</g>، <r v=\"Matt.6.2\"></r>، <r v=\"Matt.6.3\"></r>، <r v=\"Acts.9.36\"></r>، <r v=\"Acts.10.2\"></r>، <r v=\"Acts.24.17\"></r>؛ <g>ἐ. διδόναι</g>، <r v=\"Luke.11.41\"></r> (قارن <r v=\"Matt.23.36\"></r>)، 12:33؛ <g>αἰτεῖν</g>، <r v=\"Acts.3.2\"></r>؛ <g>λαβεῖν</g>، <r v=\"Acts.3.3\"></r>؛ <g>πρὸς</g> (لكي يطلب) <g>ἐ.</g>، <r v=\"Acts.3.10\"></r>؛ جمع، <r v=\"Acts.10.4\"></r>، <r v=\"Acts.10.31\"></r>.†</s>","en":"<f>† <o>ἐλεημοσύνη</o>, <g>-ης, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>ἐλεέω</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2617\">חֶסֶד</h>, <h n=\"H6666\">צְדָקָה</h> ;] </e> </et> <s n=\"1.\"><b>mercy, pity</b>. </s> <s n=\"2.\"><b>almsgiving, alms</b> (like the German <i>Almosen</i>, a corruption of the Greek word <g>ἐ</g>): <r v=\"Matt.6.4\"></r>; <g>ποιεῖν ἐ.</g>, <r v=\"Matt.6.2\"></r>, <r v=\"Matt.6.3\"></r>, <r v=\"Acts.9.36\"></r> <r v=\"Acts.10.2\"></r> <r v=\"Acts.24.17\"></r>; <g>ἐ. διδόναι</g>, <r v=\"Luke.11.41\"></r> (cf. <r v=\"Matt.23.36\"></r>; Dalman, <i>Words</i>, 62 f.) 12:33; <g>αἰτεῖν</g>, <r v=\"Acts.3.2\"></r>; <g>λαβεῖν</g>, <r v=\"Acts.3.3\"></r>; <g>πρὸς</g> (in order to ask) <g>ἐ.</g>, <r v=\"Acts.3.10\"></r>; pl., <r v=\"Acts.10.4\"></r>, <r v=\"Acts.10.31\"></r> (Cremer, 711).†</s>"},"G1634":{"l":"ἐκψύχω","o":3,"ar":"<f><o>ἐκ-ψύχω </o></f> <s><b>أسلم الروح، لفظ أنفاسه الأخيرة</b>: <r v=\"Acts.5.5\"></r>، <r v=\"Acts.5.10\"></r>، <r v=\"Acts.12.23\"></r> (قارن <g>ἐκπνέω</g>).†</s>","en":"<f><o>ἐκ-ψύχω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Judg.4.21\"></r> A (<h n=\"H5774\">עוּף</h>), <r v=\"Ezek.21.7\"></r> (<h n=\"H3543\">כָּהָה</h> pi.)* ;]</e> </et> <s><b>to expire, breathe one's last</b>: <r v=\"Acts.5.5\"></r>, <r v=\"Acts.5.10\"></r> <r v=\"Acts.12.23\"></r> (cf. <g>ἐκπνέω</g>; Cremer, 906).†</s>"},"G1664":{"l":"Ἐλιούδ","o":2,"ar":"<f><o>Ἐλιούδ</o>، <g>ὁ </g></f> <s>لا يُصرَّف، </s> <s><b>أليود</b>، أحد أسلاف يسوع: <r v=\"Matt.1.14\"></r>، <r v=\"Matt.1.15\"></r>.† </s>","en":"<f><o>Ἐλιούδ</o>, <g>ὁ </g></f> <s>indecl., </s> <s><b>Eliud</b>, an ancestor of Jesus: <r v=\"Matt.1.14\"></r>, <r v=\"Matt.1.15\"></r>.† </s>"},"G1604":{"l":"ἐκπλήρωσις","o":1,"ar":"<f>**† <o>ἐκ-πλήρωσις, -εως, ἡ</o>) </f> <s><b>إكمال، إتمام</b>: <r v=\"Acts.21.26\"></r>.†</s>","en":"<f>**† <o>ἐκ-πλήρωσις, -εως, ἡ</o>) </f> <et> <e t=\"septuagint\">[in LXX: <r v=\"2Macc.6.14\"></r> * ;]</e> </et> <s><b>a completion, fulfilment</b>: <r v=\"Acts.21.26\"></r>.†</s>"},"G1614":{"l":"ἐκτείνω","o":16,"ar":"<f><o>ἐκ-τείνω </o></f> <s><b>مدّ، بسط</b>: <g>τ. χεῖρα</g> (كما كثيرًا في السبعينية)، <r v=\"Matt.8.3\"></r> <r v=\"Matt.12.13\"></r> <r v=\"Matt.14.31\"></r> <r v=\"Matt.26.51\"></r>، <r v=\"Mark.1.41\"></r> <r v=\"Mark.3.5\"></r>، <r v=\"Luke.5.13\"></r> <r v=\"Luke.6.10\"></r> <r v=\"John.21.18\"></r>، <r v=\"Acts.26.1\"></r>؛ يليه <g>ἐπί</g>، مع منصوب الشخص، <b>نحو</b>، <r v=\"Matt.12.49\"></r>؛ <b>على (ضد)</b>، <r v=\"Luke.22.53\"></r>؛ <g>εἰς ἴασιν</g>، <r v=\"Acts.4.30\"></r>؛ عن المراسي، <b>ألقى</b>، <r v=\"Acts.27.30\"></r>.†</s>","en":"<f><o>ἐκ-τείνω </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H7971\">שָׁלַח</h>, <h n=\"H5186\">נָטָה</h>, etc. ;]</e> </et> <s><b>to stretch out or forth</b>: <g>τ. χεῖρα</g> (as often in LXX), <r v=\"Matt.8.3\"></r> <r v=\"Matt.12.13\"></r> <r v=\"Matt.14.31\"></r> <r v=\"Matt.26.51\"></r>, <r v=\"Mark.1.41\"></r> <r v=\"Mark.3.5\"></r>, <r v=\"Luke.5.13\"></r> <r v=\"Luke.6.10\"></r> <r v=\"John.21.18\"></r>, <r v=\"Acts.26.1\"></r>; seq. <g>ἐπί</g>, c. acc pers., <b>towards</b>, <r v=\"Matt.12.49\"></r>; <b>against</b>, <r v=\"Luke.22.53\"></r>; <g>εἰς ἴασιν</g>, <r v=\"Acts.4.30\"></r>; of anchors, <b>to cast</b>, <r v=\"Acts.27.30\"></r>.†</s>"},"G1689":{"l":"ἐμβλέπω","o":12,"ar":"<f><o>ἐμ-βλέπω </o></f> <s><b>نظر إلى، تطلّع إلى</b>: مع منصوب الشيء، <r v=\"Mark.8.25\"></r>؛ مع القابل للشخص (اسم الفاعل، يليه <g>λέγει, εἶπεν</g>)، <r v=\"Matt.19.26\"></r>، <r v=\"Mark.10.21\"></r>، <r v=\"Mark.10.27\"></r> <r v=\"Mark.14.67\"></r>، <r v=\"Luke.20.17\"></r> <r v=\"Luke.22.61\"></r> (<g>ἐνέβλεψεν</g>)، <r v=\"John.1.36\"></r>، <r v=\"John.1.43\"></r>؛ مطلقًا، <b>نظر، أبصر</b>، <r v=\"Acts.22.11\"></r>؛ مجازيًا، <b>تأمّل</b>: <r v=\"Matt.6.26\"></r>.†</s>","en":"<f><o>ἐμ-βλέπω </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H7200\">רָאָה</h>, <r v=\"1Kgs.8.8\"></r>, al.), <h n=\"H6437\">פָּנָה</h> (<r v=\"Job.6.28\"></r> A, al.); metaph., <r v=\"Isa.51.1\"></r> (<h n=\"H5027\">נָבַט</h> hi.), <r v=\"Sir.2.10\"></r>, etc. ;]</e> </et> <s><b>to look at</b>: c. acc rei, <r v=\"Mark.8.25\"></r>; c. dat. pers. (part., seq. <g>λέγει, εἶπεν</g>, cf. Xen., <i>Cyr</i>., i, 3, 2), <r v=\"Matt.19.26\"></r>, <r v=\"Mark.10.21\"></r>, <r v=\"Mark.10.27\"></r> <r v=\"Mark.14.67\"></r>, <r v=\"Luke.20.17\"></r> <r v=\"Luke.22.61\"></r> (<g>ἐνέβλεψεν</g>), <r v=\"John.1.36\"></r>, <r v=\"John.1.43\"></r>; absol., <b>to look</b>, <r v=\"Acts.22.11\"></r>; metaph., <b>to consider</b>: <r v=\"Matt.6.26\"></r>.†</s>"},"G1686":{"l":"ἐμβάπτω","o":2,"ar":"<f>* <o>ἐμ-βάπτω </o></f> <s><b>غمس في</b>: <g>τ. χεῖρα ἐν τ. τρυβλίῳ</g>، <r v=\"Matt.26.23\"></r>؛ الصيغة الوسطى، يليه <g>εἰς</g>، <r v=\"Mark.14.20\"></r>.†</s>","en":"<f>* <o>ἐμ-βάπτω </o></f> <s><b>to dip in</b>: <g>τ. χεῖρα ἐν τ. τρυβλίῳ</g>, <r v=\"Matt.26.23\"></r>; mid., seq. <g>εἰς</g>, <r v=\"Mark.14.20\"></r>.†</s>"},"G1662":{"l":"Ἐλιακείμ","o":3,"ar":"<f><o>Ἐλιακείμ</o> (بالعبرية <h n=\"H471\">אֶלְיָקִים</h>)، </f> <s><b>ألياقيم</b>، أحد أسلاف يسوع: <r v=\"Matt.1.13\"></r>، <r v=\"Luke.3.30\"></r>.†</s>","en":"<f><o>Ἐλιακείμ</o>(Heb. <h n=\"H471\">אֶלְיָקִים</h>), </f> <s><b>Eliakim</b>, an ancestor of Jesus: <r v=\"Matt.1.13\"></r>, <r v=\"Luke.3.30\"></r>.†</s>"},"G1663":{"l":"Ἐλιέζερ","o":1,"ar":"<f><o>Ἐλιέζερ</o> (بالعبرية <h n=\"H461\">אֱלִיעֶזֶר</h>)، <g>ὁ</g>، لا يُصرَّف، </f> <s><b>أليعازر</b>، أحد أسلاف يسوع: <r v=\"Luke.3.29\"></r>.†</s>","en":"<f><o>Ἐλιέζερ</o>(Heb. <h n=\"H461\">אֱלִיעֶזֶר</h>), <g>ὁ</g>, indecl., </f> <s><b>Eliezer</b>, an ancestor of Jesus: <r v=\"Luke.3.29\"></r>.†</s>"},"G1685":{"l":"ἐμβάλλω","o":1,"ar":"<f><o>ἐμ-βάλλω </o></f> <s><b>ألقى في</b>: يليه <g>εἰς</g>، <r v=\"Luke.12.5\"></r>.†</s>","en":"<f><o>ἐμ-βάλλω </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H7760\">שׂוּם</h>, etc. ;] </e> </et> <s><b>to cast into</b>: seq. <g>εἰς</g>, <r v=\"Luke.12.5\"></r> (cf. MM, <i>Exp.</i>, vii, 93).†</s>"},"G1633":{"l":"εκχωρέω","o":null,"ar":"<f><o>εκ-χωρέω, -ῶ </o></f> <s><b>خرج، انصرف</b>: <r v=\"Luke.21.21\"></r>.†</s>","en":"<f><o>εκ-χωρέω, -ῶ </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Num.16.45\"></r> (<h n=\"H7311\">רוּם</h> ni.), <r v=\"Judg.7.3\"></r> (<h n=\"H6852\">צָפַר</h>), <r v=\"Amos.7.12\"></r> (<h n=\"H1272\">בָּרַח</h>), <r v=\"1Esd.4.44\"></r>, <r v=\"1Esd.4.57\"></r>, <r v=\"1Macc.9.62\"></r> * ;]</e> </et> <s><b>to depart, withdraw</b>: <r v=\"Luke.21.21\"></r>.†</s>"},"G1684":{"l":"ἐμβαίνω","o":16,"ar":"<f><o>ἐμ-βαίνω </o></f> <s><b>دخل، خطا إلى</b>: <r v=\"John.5.4\"></r>؛ <g>εἰς πλοῖον</g>، <b>ركب السفينة</b>: <r v=\"Matt.8.23\"></r> <r v=\"Matt.9.1\"></r> <r v=\"Matt.13.2\"></r> <r v=\"Matt.14.22\"></r> <r v=\"Matt.15.39\"></r>، <r v=\"Mark.4.1\"></r> <r v=\"Mark.5.18\"></r> <r v=\"Mark.6.45\"></r> <r v=\"Mark.8.10\"></r>، <r v=\"Mark.8.13\"></r>، <r v=\"Luke.5.3\"></r> <r v=\"Luke.8.22\"></r>، <r v=\"Luke.8.37\"></r>، <r v=\"John.6.17\"></r>، <r v=\"John.6.24\"></r> <r v=\"John.21.3\"></r>، <r v=\"Acts.21.6\"></r>.†</s>","en":"<f><o>ἐμ-βαίνω </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H5927\">עָלָה</h>, etc. ;] </e> </et> <s><b>to step into</b>: <r v=\"John.5.4\"></r> (WH, RV omit); <g>εἰς πλοῖον</g>, <b>to embark</b>: <r v=\"Matt.8.23\"></r> <r v=\"Matt.9.1\"></r> <r v=\"Matt.13.2\"></r> <r v=\"Matt.14.22\"></r> <r v=\"Matt.15.39\"></r>, <r v=\"Mark.4.1\"></r> <r v=\"Mark.5.18\"></r> <r v=\"Mark.6.45\"></r> <r v=\"Mark.8.10\"></r>, <r v=\"Mark.8.13\"></r>, <r v=\"Luke.5.3\"></r> <r v=\"Luke.8.22\"></r>, <r v=\"Luke.8.37\"></r>, <r v=\"John.6.17\"></r>, <r v=\"John.6.24\"></r> <r v=\"John.21.3\"></r>, <r v=\"Acts.21.6\"></r>.†</s>"},"G1620":{"l":"ἐκτίθημι","o":4,"ar":"<f><o>ἐκ-τίθημι </o></f> <s><b>أخرج، عرّض (للطرح)</b>: <r v=\"Acts.7.21\"></r>، مجازيًا، <b>عرض، شرح</b>: <r v=\"Acts.11.4\"></r> <r v=\"Acts.28.23\"></r>؛ مع منصوب الشيء، <r v=\"Acts.18.26\"></r>.†</s>","en":"<f><o>ἐκ-τίθημι </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H5414\">נָתַן</h> ni., etc. ;] </e> </et> <s><b>to set out, expose</b>: <r v=\"Acts.7.21\"></r>, Metaph., <b>to set forth, expound</b>: <r v=\"Acts.11.4\"></r> <r v=\"Acts.28.23\"></r>; c. acc rei, <r v=\"Acts.18.26\"></r>.†</s>"},"G1605":{"l":"ἐκπλήσσω","o":13,"ar":"<f><o>ἐκ-πλήσσω</o></f> <s n=\"1.\">أصلاً، <b>ضرب فأخرج، طرد</b>. </s> <s n=\"2.\"><b>أصاب بالذعر أو الصدمة، أدهش، بهت</b>: المبني للمجهول، <r v=\"Matt.13.54\"></r> <r v=\"Matt.19.25\"></r>، <r v=\"Mark.6.2\"></r> <r v=\"Mark.7.37\"></r> <r v=\"Mark.10.26\"></r>، <r v=\"Luke.2.48\"></r>؛ يليه <g>ἐπί</g> مع القابل للشيء، <r v=\"Matt.7.28\"></r> <r v=\"Matt.22.33\"></r>، <r v=\"Mark.1.22\"></r> <r v=\"Mark.11.18\"></r>، <r v=\"Luke.4.32\"></r> <r v=\"Luke.9.43\"></r>، <r v=\"Acts.13.12\"></r>.†</s> <s><g>τρεμεῖν</g>، <i>ارتعد</i>، والغالب فيه المعنى الجسدي؛ </s> <s><g>φοβεῖν</g>، <i>خاف</i>، وهو «اللفظ العام»؛ </s> <s>وقارن أيضًا <g>φρίσσω</g>، <i>اقشعرّ</i>، وانظر تحت مدخل <x><g>δειλία</g></x> </s>","en":"<f><o>ἐκ-πλήσσω</o></f> <et> <e t=\"derivation\">(Attic <g>-ττω</g>, <r v=\"Acts.13.12\"></r>), </e> <e t=\"septuagint\">[in LXX: (pass.) <r v=\"Eccl.7.16\"></r>, (<h n=\"H8074\">שָׁמֵם</h> hithp.), <r v=\"Wis.13.4\"></r>, <r v=\"2Macc.7.12\"></r>, <r v=\"4Macc.8.4\"></r> <r v=\"4Macc.17.16\"></r> * ;] </e> </et> <s n=\"1.\">prop., <b>to strike out, drive away</b>. </s> <s n=\"2.\"><b>to strike with panic or shock, to amaze, astonish</b>: pass., <r v=\"Matt.13.54\"></r> <r v=\"Matt.19.25\"></r>, <r v=\"Mark.6.2\"></r> <r v=\"Mark.7.37\"></r> <r v=\"Mark.10.26\"></r>, <r v=\"Luke.2.48\"></r>; seq. <g>ἐπί</g>, c. dat. rei, <r v=\"Matt.7.28\"></r> <r v=\"Matt.22.33\"></r>, <r v=\"Mark.1.22\"></r> <r v=\"Mark.11.18\"></r>, <r v=\"Luke.4.32\"></r> <r v=\"Luke.9.43\"></r>, <r v=\"Acts.13.12\"></r>.†</s> <sy><i>SYN.</i>: \" <g>πτωεῖν</g>, <i>to terrify, agitate with fear</i>; </sy> <s><g>τρεμεῖν</g>, <i>to tremble</i>, predominantly physical; </s> <s><g>φοβεῖν</g>, <i>to fear</i>, \"the general term,\" Thayer; </s> <s>cf. also <g>φρίσσω</g>, <i>to shudder</i>, and v.s. <x><g>δειλία</g></x> </s>"},"G1690":{"l":"ἐμβριμάομαι","o":5,"ar":"<f><o>ἐμ-βριμάομαι</o>، <g>-ῶμαι</g> </f> <f>فعل لازم الصيغة الوسطى، والماضي البسيط منه بالصيغة الوسطى والمبني للمجهول، </f> <s><b>نخر</b> (في الكلاسيكية: عن الخيل)، ومن ثم تكلّم أو تصرّف بانفعال عميق؛ </s> <s n=\"(a)\"><b>اغتاظ، اضطرم غضبًا</b> (قارن <g>ἐμβρίμημα</g>، <r v=\"Lam.2.6\"></r>): مع القابل، <r v=\"Mark.14.5\"></r>، <r v=\"John.11.33\"></r>؛ <g>ἐν ἑαυτῷ</g>، <r v=\"John.11.38\"></r>؛ </s> <s n=\"(b)\"><b>انتهر، أوصى بشدة</b>: مع القابل، <r v=\"Matt.9.30\"></r>، <r v=\"Mark.1.43\"></r>.†</s>","en":"<f><o>ἐμ-βριμάομαι</o> (T, <g>-έομαι</g>; Bl., § 22, 1), <g>-ῶμαι</g> </f> <et> <e t=\"derivation\">(&lt; <g>βρίμη</g>, <b>strength, bulk</b>, whence <g>βριμάομαι</g>, <b>to snort with anger</b>), </e> </et> <f>depon., with aor. mid. and pass., </f> <et> <e t=\"septuagint\">[in LXX (Hatch, <i>Essays</i>, 25): <r v=\"Dan.11.30\"></r> (also Aq., <r v=\"Ps.7.12\"></r>; Sm., <r v=\"Isa.17.13\"></r>) * ;] </e> </et> <s><b>to snort in</b> (of horses, Æsch.), hence, to speak or act with deep feeling (<i>DCG</i>, i, 62b); </s> <s n=\"(a)\"><b>to be moved with anger</b> (cf. <g>ἐμβρίμημα</g>, <r v=\"Lam.2.6\"></r>): c. dat., <r v=\"Mark.14.5\"></r>, <r v=\"John.11.33\"></r>; <g>ἐν ἑαυτῷ</g>, <r v=\"John.11.38\"></r>; </s> <s n=\"(b)\"><b>to admonish sternly</b>: c. dat., <r v=\"Matt.9.30\"></r>, <r v=\"Mark.1.43\"></r>.†</s>"},"G1606":{"l":"ἐκπνέω","o":3,"ar":"<f>* <o>ἐκ-πνέω, -ῶ</o>، </f> <s><b>زفر، أخرج النفَس</b>؛ والمقدَّر <g>βίον</g>، <g>ψυχήν</g> (ويُذكر صراحةً في الكلاسيكية)، <b>لفظ نفَسه الأخير، أسلم الروح</b>: <r v=\"Mark.15.37\"></r>، <r v=\"Mark.15.39\"></r> <r v=\"Luke.23.46\"></r>. وعن دلالة الماضي البسيط، قارن <r v=\"Mark.15.37\"></r>.†</s>","en":"<f>* <o>ἐκ-πνέω, -ῶ</o>, </f> <s><b>to breathe out</b>; sc. <g>βίον</g>, <g>ψυχήν</g> (expressed in cl., Æsch., al.; cf. LS, s.v.), <b>to breathe one's last, expire</b>: <r v=\"Mark.15.37\"></r>, <r v=\"Mark.15.39\"></r> <r v=\"Luke.23.46\"></r>. For force of aorist, v. Swete, <r v=\"Mark.15.37\"></r>.†</s>"},"G1676":{"l":"Ἑλληνιστί","o":2,"ar":"<f>* <o>Ἑλληνιστί </o></f> ظرف، <s><b>باليونانية</b>: <r v=\"John.19.20\"></r>؛ <g>Ἑ.</g> (والمقدَّر <g>λαλεῖν</g>) <g>γινώσκεις</g>، <r v=\"Acts.21.37\"></r>.†</s>","en":"<f>* <o>Ἑλληνιστί </o></f> adv., <s><b>in Greek</b>: <r v=\"John.19.20\"></r>; <g>Ἑ.</g> (sc. <g>λαλεῖν</g>) <g>γινώσκεις</g>, <r v=\"Acts.21.37\"></r> (cf. Field, <i>Notes</i>, 135).†</s>"},"G1603":{"l":"ἐκπληρόω","o":1,"ar":"<f>** <o>ἐκ-πληρόω </o></f> <s n=\"1.\"><b>ملأ تمامًا، أكمل العدد</b>. </s> <s n=\"2.\"><b>أتمّ</b>، <r v=\"Acts.13.32\"></r>.†</s>","en":"<f>** <o>ἐκ-πληρόω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"2Macc.8.10\"></r>, <r v=\"3Macc.1.2\"></r>, <r v=\"3Macc.1.22\"></r> * ;] </e> </et> <s n=\"1.\"><b>to fill full, make up a number</b>. </s> <s n=\"2.\"><b>to fulfil</b> (MM, <i>Exp.</i>, xii; Cremer, 839), <r v=\"Acts.13.32\"></r>.†</s>"},"G1675":{"l":"Ἑλληνιστής","o":3,"ar":"<f>*† <o>Ἑλληνιστής</o>، <g>-οῦ, ὁ</g></f> <s><b>هلّينستي</b> (في الترجمة المنقحة:<b> يهودي يوناني اللسان</b>): <r v=\"Acts.6.1\"></r> <r v=\"Acts.9.29\"></r> <r v=\"Acts.11.20\"></r>.†</s>","en":"<f>*† <o>Ἑλληνιστής</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>Ἑλληνίζω</g>, <b>to Hellenize, affect Greek cus­toms)</b>, </e> </et> <s><b>a Hellenist</b> (RV,<b> Grecian Jew</b>): <r v=\"Acts.6.1\"></r> <r v=\"Acts.9.29\"></r> <r v=\"Acts.11.20\"></r>.†</s>"},"G1631":{"l":"ἐκφύω","o":2,"ar":"<f>** <o>ἐκ-φύω </o></f> <s><b>أنبت، أخرج</b> (الأوراق): <r v=\"Matt.24.32\"></r>، <r v=\"Mark.13.28\"></r>.†</s>","en":"<f>** <o>ἐκ-φύω </o></f> <et> <e t=\"septuagint\">[in OT (Sm.) <r v=\"Ps.104.14\"></r>; (Al.) <r v=\"Isa.61.11\"></r> * ;] </e> </et> <s><b>to cause to grow out, put forth</b> (leaves): <r v=\"Matt.24.32\"></r>, <r v=\"Mark.13.28\"></r>.†</s>"},"G1695":{"l":"Ἐμμαούς","o":1,"ar":"<f><o>Ἐμμαούς</o>، <g>ἡ</g></f> <s><b>عمواس</b>، موضع على بعد 60 غلوة من أورشليم: <r v=\"Luke.24.13\"></r>.†</s>","en":"<f><o>Ἐμμαούς</o>, <g>ἡ</g></f> <s><b>Emmaus</b>, a place 60 furlongs from Jerusalem: <r v=\"Luke.24.13\"></r>.†</s>"},"G1682":{"l":"ἐλωί","o":2,"ar":"<f><o>ἐλωί</o></f> <s><b>إلوي</b>: <r v=\"Matt.27.46\"></r>، <r v=\"Mark.15.34\"></r> <i>(السبعينية)</i>.†</s>","en":"<f><o>ἐλωί</o></f> <et> <e t=\"derivation\">(<g>-ΐ</g> Rec.; <g>ἑλωΐ</g> LT; Aram. <h n=\"H426\">אֱלָהּ</h>), </e> </et> <s><b>Eloi</b>: <r v=\"Matt.27.46\"></r>, <r v=\"Mark.15.34\"></r> <i>(LXX)</i>.†</s>"},"G1611":{"l":"ἔκστασις","o":7,"ar":"<f><o>ἔκ-στασις</o>، <g>-εως, ἡ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>إزاحة</b>. </s> <s n=\"2.\">حالة غير عادية للعقل، يخرج فيها المرء عن ضبطه المعتاد لنفسه؛ وفي العهد الجديد: </s> <s n=\"(a)\"><b>غيبة</b>: <r v=\"Acts.10.10\"></r> <r v=\"Acts.11.5\"></r> <r v=\"Acts.22.17\"></r>؛ </s> <s n=\"(b)\"><b>دهشة، حيرة</b>: <r v=\"Mark.5.42\"></r> <r v=\"Mark.16.8\"></r>، <r v=\"Luke.5.26\"></r>، <r v=\"Acts.3.10\"></r>.†</s>","en":"<f><o>ἔκ-στασις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(<g>ἐξίστημι</g>) </e> <e t=\"septuagint\">[in LXX: <r v=\"Gen.27.33\"></r>, <r v=\"1Sam.14.15\"></r>, <r v=\"Ezek.26.16\"></r>, al. (<h n=\"H2731\">חֲרָדָה</h>); <r v=\"2Chr.14.14\"></r> <r v=\"2Chr.17.10\"></r> <r v=\"2Chr.20.29\"></r> (<h n=\"H6343\">פַּחַד</h>), al. ;] </e> </et> <s n=\"1.\"><b>a displacement</b> (Arist.). </s> <s n=\"2.\">An abnormal condition of the mind, in which the subject passes out of his usual self-control (Hippocr.); in NT (Kennedy, <i>Sources</i>, 121 f.); </s> <s n=\"(a)\"><b>a trance</b>: <r v=\"Acts.10.10\"></r> <r v=\"Acts.11.5\"></r> <r v=\"Acts.22.17\"></r>; </s> <s n=\"(b)\"><b>amazement</b>: <r v=\"Mark.5.42\"></r> <r v=\"Mark.16.8\"></r>, <r v=\"Luke.5.26\"></r>, <r v=\"Acts.3.10\"></r>.†</s>"},"G1621":{"l":"ἐκτινάσσω","o":4,"ar":"<f><o>ἐκ-τινάσσω </o></f> <s><b>نفض</b>: <g>κονιορτόν</g>، <r v=\"Matt.10.14\"></r>؛ <g>χοῦν</g>، <r v=\"Mark.6.11\"></r>. الصيغة الوسطى: <g>κονιορτόν</g>، <r v=\"Acts.13.51\"></r>؛ <g>ἱμάτια</g>، <r v=\"Acts.18.6\"></r>.†</s>","en":"<f><o>ἐκ-τινάσσω </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H5287\">נָעַר</h> ni., pi., etc. ;]</e> </et> <s><b>to shake off</b>: <g>κονιορτόν</g>, <r v=\"Matt.10.14\"></r>; <g>χοῦν</g>, <r v=\"Mark.6.11\"></r>. Mid.: <g>κονιορτόν</g>, <r v=\"Acts.13.51\"></r>; <g>ἱμάτια</g>, <r v=\"Acts.18.6\"></r> (cf. MM, <i>Exp.</i>, iii).†</s>"},"G1688":{"l":"ἐμβιβάζω","o":1,"ar":"<f><o>ἐμ-βιβάζω </o></f> <s n=\"1.\"><b>أدخل، وضع في</b>. </s> <s n=\"2.\"><b>أصعد</b> إلى السفينة، <b>أركب</b>: مع منصوب الشخص، يليه <g>εἰς</g>، <r v=\"Acts.27.6\"></r>.†</s>","en":"<f><o>ἐμ-βιβάζω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"2Kgs.9.23\"></r> (<h n=\"H7392\">רָכַב</h> hi.), <r v=\"Prov.4.11\"></r> (<h n=\"H1869\">דָּרַךְ</h> hi.) * ;] </e> </et> <s n=\"1.\"><b>to set in, put in</b>. </s> <s n=\"2.\"><b>to put on board</b> ship, <b>embark</b>: c. acc pers., seq. <g>εἰς</g>, <r v=\"Acts.27.6\"></r>.†</s>"},"G1665":{"l":"Ἐλεισάβετ","o":9,"ar":"<f><o>Ἐλεισάβετ</o>، <g>ἡ</g> لا يُصرَّف (من العبرية <h n=\"H472\">אֱלִישֶׁבַע</h>) </f> <s><b>أليصابات</b>: <r v=\"Luke.1.5\"></r> وما يليه.†</s>","en":"<f><o>Ἐλεισάβετ</o> (T, Rec. <g>Ἐλισ-</g>; v. WH, <i>App.</i>, 155), <g>ἡ</g> indecl. (Heb. <h n=\"H472\">אֱלִישֶׁבַע</h>) </f> <s><b>Elizabeth</b>: <r v=\"Luke.1.5\"></r> ff.†</s>"},"G1648":{"l":"Ἐλεάζαρ","o":2,"ar":"<f><o>Ἐλεάζαρ</o> (من العبرية <h n=\"H499\">אֶלְעָזָר</h>)، <g>ὁ</g>، لا يُصرَّف، </f> <s><b>أليعازر</b>: <r v=\"Matt.1.15\"></r>.†</s>","en":"<f><o>Ἐλεάζαρ</o>(Heb. <h n=\"H499\">אֶלְעָזָר</h>), <g>ὁ</g>, indecl., </f> <s><b>Eleazar</b>: <r v=\"Matt.1.15\"></r>.†</s>"}});A.got[16]=1})(window.ABBOTT=window.ABBOTT||{D:{},got:{}});